{
  "name": "GrammatiCat: El Desafío de las Palabras",
  "description": "Un juego educativo dinámico para practicar clases de palabras con un editor inteligente impulsado por IA y un modo secreto oculto."
}

export enum WordClass {
  SUSTANTIVO = 'Sustantivo',
  ADJETIVO = 'Adjetivo',
  VERBO = 'Verbo',
  ADVERBIO = 'Adverbio',
  PRONOMBRE = 'Pronombre',
  PREPOSICION = 'Preposición',
  CONJUNCION = 'Conjunción',
  DETERMINANTE = 'Determinante'
}

export interface WordData {
  text: string;
  category: WordClass;
  id: string;
}

export interface Level {
  id: number;
  title: string;
  text: string;
  targetCategory: WordClass;
  words: WordData[];
  timeLimit: number;
}

export interface GameState {
  score: number;
  lives: number;
  time: number;
  levelIndex: number;
  isPlaying: boolean;
  isGameOver: boolean;
  powerups: {
    hints: number;
    shields: number;
    cleaners: number;
  };
}

export enum GameView {
  MENU = 'MENU',
  PLAYING = 'PLAYING',
  EDITOR = 'EDITOR',
  GAME_OVER = 'GAME_OVER'
}

import { WordClass, Level } from './types';

export const INITIAL_LEVELS: Level[] = [
  {
    id: 1,
    title: "El Bosque Mágico",
    text: "El gato negro corre rápido por el bosque verde y saltó sobre una rama pequeña.",
    targetCategory: WordClass.SUSTANTIVO,
    words: [], // Processed at runtime or editor
    timeLimit: 30
  },
  {
    id: 2,
    title: "La Aventura Espacial",
    text: "Los astronautas valientes exploran planetas lejanos con sus naves plateadas muy velozmente.",
    targetCategory: WordClass.ADJETIVO,
    words: [],
    timeLimit: 25
  },
  {
    id: 3,
    title: "Receta de Cocina",
    text: "Nosotros cocinaremos hoy una tarta deliciosa porque tenemos mucha hambre.",
    targetCategory: WordClass.VERBO,
    words: [],
    timeLimit: 20
  }
];

export const KONAMI_CODE = [
  'ArrowUp', 'ArrowUp', 'ArrowDown', 'ArrowDown',
  'ArrowLeft', 'ArrowRight', 'ArrowLeft', 'ArrowRight',
  'b', 'a'
];

import { GoogleGenAI, Type } from "@google/genai";
import { WordClass } from "../types";

export const analyzeTextWithAI = async (text: string) => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analiza el siguiente texto en español y clasifica cada palabra según su clase gramatical (Sustantivo, Adjetivo, Verbo, Adverbio, Pronombre, Preposición, Conjunción, Determinante). Ignora signos de puntuación.

    Texto: "${text}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            text: { type: Type.STRING },
            category: { 
              type: Type.STRING,
              description: "Una de: Sustantivo, Adjetivo, Verbo, Adverbio, Pronombre, Preposición, Conjunción, Determinante"
            }
          },
          required: ["text", "category"]
        }
      }
    }
  });

  try {
    const data = JSON.parse(response.text);
    return data;
  } catch (e) {
    console.error("Error parsing Gemini response", e);
    return [];
  }
};

