import React, { useState } from 'react';
import { WordClass, Level, WordData } from '../types';
import { analyzeTextWithAI } from '../services/geminiService';

interface Props {
  onSave: (level: Level) => void;
  onClose: () => void;
}

export const Editor: React.FC<Props> = ({ onSave, onClose }) => {
  const [text, setText] = useState('');
  const [title, setTitle] = useState('');
  const [targetCategory, setTargetCategory] = useState<WordClass>(WordClass.SUSTANTIVO);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analyzedWords, setAnalyzedWords] = useState<WordData[]>([]);

  const handleAnalyze = async () => {
    if (!text.trim()) return;
    setIsAnalyzing(true);
    const result = await analyzeTextWithAI(text);
    const formatted = result.map((w: any, idx: number) => ({
      ...w,
      id: `${idx}-${Date.now()}`
    }));
    setAnalyzedWords(formatted);
    setIsAnalyzing(false);
  };

  const handleSave = () => {
    const newLevel: Level = {
      id: Date.now(),
      title: title || "Nivel Personalizado",
      text,
      targetCategory,
      words: analyzedWords,
      timeLimit: 30
    };
    onSave(newLevel);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-indigo-950/80 backdrop-blur-md p-4">
      <div className="bg-white w-full max-w-4xl rounded-3xl overflow-hidden flex flex-col max-h-[90vh] shadow-2xl border-8 border-indigo-400">
        <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
          <h2 className="text-3xl font-black italic tracking-tighter">EDITOR SECRETO <span className="text-yellow-400">GEMINI IA</span></h2>
          <button onClick={onClose} className="hover:bg-indigo-700 p-2 rounded-full transition-colors">
            <i className="fas fa-times text-2xl"></i>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-400 uppercase">Título del Nivel</label>
              <input 
                value={title}
                onChange={e => setTitle(e.target.value)}
                className="w-full p-4 rounded-xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-bold"
                placeholder="Ej: El misterio de las letras..."
              />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-400 uppercase">Categoría Objetivo</label>
              <select 
                value={targetCategory}
                onChange={e => setTargetCategory(e.target.value as WordClass)}
                className="w-full p-4 rounded-xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-bold"
              >
                {Object.values(WordClass).map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-400 uppercase">Texto a Analizar</label>
            <textarea 
              value={text}
              onChange={e => setText(e.target.value)}
              className="w-full h-32 p-4 rounded-xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-medium text-lg leading-relaxed"
              placeholder="Pega tu texto aquí..."
            />
          </div>

          <button 
            onClick={handleAnalyze}
            disabled={isAnalyzing || !text}
            className={`w-full py-4 rounded-2xl text-white font-black text-xl shadow-lg transition-all ${isAnalyzing ? 'bg-gray-400' : 'bg-gradient-to-r from-indigo-500 to-purple-500 hover:scale-[1.02] active:scale-95'}`}
          >
            {isAnalyzing ? <><i className="fas fa-spinner fa-spin mr-2"></i>ANALIZANDO...</> : 'ANALIZAR CON INTELIGENCIA ARTIFICIAL'}
          </button>

          {analyzedWords.length > 0 && (
            <div className="p-6 bg-slate-50 rounded-2xl border-2 border-slate-200">
              <h3 className="text-sm font-bold text-slate-500 uppercase mb-4">Revisión de Clases:</h3>
              <div className="flex flex-wrap gap-2">
                {analyzedWords.map((w, i) => (
                  <div key={i} className="group relative bg-white px-3 py-1 rounded-lg border border-slate-300 hover:border-indigo-400 cursor-help flex items-center">
                    <span className="font-medium mr-2">{w.text}</span>
                    <span className="text-[10px] px-1.5 py-0.5 bg-indigo-100 text-indigo-600 rounded font-bold uppercase">{w.category}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="p-6 bg-slate-100 border-t flex justify-end">
          <button 
            onClick={handleSave}
            className="px-8 py-3 bg-green-500 hover:bg-green-600 text-white font-black rounded-xl shadow-lg transition-all active:scale-95"
          >
            GUARDAR Y JUGAR NIVEL
          </button>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GameView, GameState, WordClass, Level, WordData } from './types';
import { INITIAL_LEVELS, KONAMI_CODE } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';

const App: React.FC = () => {
  const [view, setView] = useState<GameView>(GameView.MENU);
  const [gameState, setGameState] = useState<GameState>({
    score: 0,
    lives: 3,
    time: 0,
    levelIndex: 0,
    isPlaying: false,
    isGameOver: false,
    powerups: { hints: 2, shields: 1, cleaners: 1 }
  });
  const [levels, setLevels] = useState<Level[]>(INITIAL_LEVELS);
  const [currentLevel, setCurrentLevel] = useState<Level | null>(null);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [errorWords, setErrorWords] = useState<string[]>([]);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [showKonamiEffect, setShowKonamiEffect] = useState(false);

  // Powerup effects
  const [highlightActive, setHighlightActive] = useState(false);
  const [cleanedIndices, setCleanedIndices] = useState<number[]>([]);

  const timerRef = useRef<NodeJS.Timeout | null>(null);

  const startGame = (index = 0) => {
    const level = levels[index];
    if (!level) return;

    // Process text into words if not already done
    let words = level.words;
    if (words.length === 0) {
      words = level.text.split(/\s+/).map((t, i) => ({
        text: t.replace(/[.,;:]/g, ''),
        category: WordClass.SUSTANTIVO, // Fallback dummy category
        id: `${i}-${Date.now()}`
      }));
    }

    setCurrentLevel({ ...level, words });
    setGameState(prev => ({
      ...prev,
      time: level.timeLimit,
      levelIndex: index,
      isPlaying: true,
      isGameOver: false
    }));
    setFoundWords([]);
    setErrorWords([]);
    setCleanedIndices([]);
    setHighlightActive(false);
    setView(GameView.PLAYING);
  };

  const handleGameOver = (win: boolean) => {
    if (timerRef.current) clearInterval(timerRef.current);
    setView(GameView.GAME_OVER);
    setGameState(prev => ({ ...prev, isPlaying: false, isGameOver: true }));
  };

  const nextLevel = () => {
    const nextIdx = gameState.levelIndex + 1;
    if (nextIdx < levels.length) {
      startGame(nextIdx);
    } else {
      alert("¡HAS GANADO TODO EL JUEGO!");
      setView(GameView.MENU);
    }
  };

  useEffect(() => {
    if (gameState.isPlaying && gameState.time > 0) {
      timerRef.current = setInterval(() => {
        setGameState(prev => {
          if (prev.time <= 1) {
            handleGameOver(false);
            return { ...prev, time: 0 };
          }
          return { ...prev, time: prev.time - 1 };
        });
      }, 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [gameState.isPlaying, gameState.levelIndex]);

  const handleWordClick = (word: WordData, index: number) => {
    if (!gameState.isPlaying || !currentLevel) return;
    if (foundWords.includes(word.id) || errorWords.includes(word.id)) return;

    if (word.category === currentLevel.targetCategory) {
      const newFound = [...foundWords, word.id];
      setFoundWords(newFound);
      setGameState(prev => ({ ...prev, score: prev.score + 10 }));

      // Check level completion
      const targetWordsCount = currentLevel.words.filter(w => w.category === currentLevel.targetCategory).length;
      if (newFound.length === targetWordsCount && targetWordsCount > 0) {
        setTimeout(() => nextLevel(), 1000);
      }
    } else {
      setErrorWords(prev => [...prev, word.id]);
      setGameState(prev => {
        const newLives = prev.lives - 1;
        if (newLives <= 0) {
          handleGameOver(false);
          return { ...prev, lives: 0, time: 0 };
        }
        return { ...prev, lives: newLives, time: Math.max(0, prev.time - 5) };
      });
    }
  };

  const useHint = () => {
    if (gameState.powerups.hints <= 0 || !currentLevel) return;
    const targets = currentLevel.words.filter(w => w.category === currentLevel.targetCategory && !foundWords.includes(w.id));
    if (targets.length > 0) {
      const random = targets[Math.floor(Math.random() * targets.length)];
      handleWordClick(random, currentLevel.words.indexOf(random));
      setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, hints: prev.powerups.hints - 1 } }));
    }
  };

  const useCleaner = () => {
    if (gameState.powerups.cleaners <= 0 || !currentLevel) return;
    const wrongOnes = currentLevel.words
      .map((w, i) => ({ w, i }))
      .filter(item => item.w.category !== currentLevel.targetCategory && !errorWords.includes(item.w.id) && !cleanedIndices.includes(item.i));

    const count = Math.min(3, wrongOnes.length);
    const toClean = [];
    for (let i = 0; i < count; i++) {
      const idx = Math.floor(Math.random() * wrongOnes.length);
      toClean.push(wrongOnes[idx].i);
      wrongOnes.splice(idx, 1);
    }
    setCleanedIndices(prev => [...prev, ...toClean]);
    setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, cleaners: prev.powerups.cleaners - 1 } }));
  };

  // Konami Code Detection
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const nextProgress = [...konamiProgress, e.key];
      const matchLength = nextProgress.length;
      const expected = KONAMI_CODE.slice(0, matchLength);

      if (JSON.stringify(nextProgress) === JSON.stringify(expected)) {
        if (matchLength === KONAMI_CODE.length) {
          setShowKonamiEffect(true);
          setView(GameView.EDITOR);
          setKonamiProgress([]);
        } else {
          setKonamiProgress(nextProgress);
        }
      } else {
        setKonamiProgress([]);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress]);

  return (
    <div className={`min-h-screen w-full flex flex-col items-center justify-center p-4 bg-gradient-to-br from-blue-400 via-indigo-400 to-purple-500 overflow-hidden transition-all duration-1000 ${showKonamiEffect ? 'konami-active' : ''}`}>

      {view === GameView.MENU && (
        <div className="text-center animate-in fade-in zoom-in duration-500">
          <div className="relative mb-8">
            <h1 className="text-8xl font-black text-white italic drop-shadow-[0_10px_10px_rgba(0,0,0,0.3)] tracking-tighter">
              GRAMMA<span className="text-yellow-300">CAT</span>
            </h1>
            <div className="absolute -top-12 -right-12 rotate-12 bg-white px-4 py-2 rounded-2xl shadow-lg border-4 border-indigo-600">
              <span className="text-2xl font-bold text-indigo-600">MEOW! 🐾</span>
            </div>
          </div>
          <p className="text-white/90 text-xl font-medium mb-12 max-w-md mx-auto leading-relaxed">
            Domina las categorías gramaticales en este desafío contrarreloj lleno de sorpresas.
          </p>
          <button 
            onClick={() => startGame(0)}
            className="group relative px-12 py-6 bg-yellow-400 hover:bg-yellow-300 text-indigo-900 rounded-3xl text-4xl font-black shadow-[0_12px_0_rgb(180,120,0)] hover:translate-y-1 hover:shadow-[0_8px_0_rgb(180,120,0)] transition-all active:translate-y-3 active:shadow-none"
          >
            ¡EMPEZAR A JUGAR!
            <i className="fas fa-play ml-4 text-3xl group-hover:translate-x-2 transition-transform"></i>
          </button>

          <div className="mt-16 flex justify-center space-x-12">
            <div className="flex flex-col items-center text-white">
              <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-2xl mb-2">
                <i className="fas fa-keyboard"></i>
              </div>
              <span className="text-xs font-bold uppercase tracking-widest">Aprende</span>
            </div>
            <div className="flex flex-col items-center text-white">
              <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-2xl mb-2">
                <i className="fas fa-bolt"></i>
              </div>
              <span className="text-xs font-bold uppercase tracking-widest">Velocidad</span>
            </div>
            <div className="flex flex-col items-center text-white">
              <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-2xl mb-2">
                <i className="fas fa-trophy"></i>
              </div>
              <span className="text-xs font-bold uppercase tracking-widest">Ranking</span>
            </div>
          </div>
        </div>
      )}

      {view === GameView.PLAYING && currentLevel && (
        <div className="w-full flex flex-col items-center animate-in slide-in-from-bottom duration-500">
          <GameHUD state={gameState} target={currentLevel.targetCategory} />

          <div className="w-full max-w-4xl bg-white/90 backdrop-blur-md rounded-[3rem] p-12 shadow-2xl border-b-8 border-indigo-200 min-h-[400px] flex flex-col justify-center relative overflow-hidden">
            {/* Background pattern */}
            <div className="absolute inset-0 opacity-5 pointer-events-none">
                <div className="absolute top-0 left-0 w-full h-full" style={{backgroundImage: 'radial-gradient(#4f46e5 1px, transparent 1px)', backgroundSize: '24px 24px'}}></div>
            </div>

            <div className="relative z-10 flex flex-wrap justify-center items-center gap-x-2 gap-y-4 text-4xl font-semibold leading-relaxed tracking-tight text-slate-800">
              {currentLevel.words.map((w, i) => {
                const isFound = foundWords.includes(w.id);
                const isError = errorWords.includes(w.id);
                const isCleaned = cleanedIndices.includes(i);

                return (
                  <span 
                    key={w.id}
                    onClick={() => handleWordClick(w, i)}
                    className={`
                      cursor-pointer px-4 py-2 rounded-2xl transition-all duration-300 transform hover:scale-110 active:scale-95 select-none
                      ${isFound ? 'bg-green-400 text-white shadow-lg -rotate-2 scale-105 pointer-events-none' : ''}
                      ${isError ? 'bg-rose-400 text-white shadow-lg rotate-2 scale-105 pointer-events-none line-through opacity-50' : ''}
                      ${isCleaned ? 'opacity-20 line-through scale-90 pointer-events-none filter grayscale' : ''}
                      ${!isFound && !isError && !isCleaned ? 'hover:bg-indigo-100 hover:text-indigo-600' : ''}
                    `}
                  >
                    {w.text}
                  </span>
                );
              })}
            </div>
          </div>

          <div className="w-full max-w-4xl mt-8 flex justify-center space-x-6">
            <button 
              onClick={useHint}
              disabled={gameState.powerups.hints <= 0}
              className={`flex flex-col items-center p-4 rounded-3xl transition-all ${gameState.powerups.hints > 0 ? 'bg-amber-400 text-amber-900 shadow-lg hover:translate-y-1' : 'bg-slate-200 text-slate-400 opacity-50'}`}
            >
              <i className="fas fa-lightbulb text-3xl mb-1"></i>
              <span className="text-[10px] font-black uppercase">Pista ({gameState.powerups.hints})</span>
            </button>

            <button 
              onClick={useCleaner}
              disabled={gameState.powerups.cleaners <= 0}
              className={`flex flex-col items-center p-4 rounded-3xl transition-all ${gameState.powerups.cleaners > 0 ? 'bg-cyan-400 text-cyan-900 shadow-lg hover:translate-y-1' : 'bg-slate-200 text-slate-400 opacity-50'}`}
            >
              <i className="fas fa-broom text-3xl mb-1"></i>
              <span className="text-[10px] font-black uppercase">Limpiar ({gameState.powerups.cleaners})</span>
            </button>

            <button 
              className="flex flex-col items-center p-4 rounded-3xl bg-indigo-500 text-white shadow-lg opacity-50 cursor-not-allowed"
            >
              <i className="fas fa-shield-alt text-3xl mb-1"></i>
              <span className="text-[10px] font-black uppercase">Escudo (0)</span>
            </button>
          </div>
        </div>
      )}

      {view === GameView.GAME_OVER && (
        <div className="text-center bg-white p-12 rounded-[3rem] shadow-2xl border-8 border-rose-500 animate-in zoom-in duration-300">
          <i className="fas fa-skull-crossbones text-7xl text-rose-500 mb-6"></i>
          <h2 className="text-6xl font-black text-slate-900 italic tracking-tighter mb-4">GAME OVER</h2>
          <p className="text-2xl font-bold text-slate-500 mb-8">¡Pero no te rindas! ¡El conocimiento es poder!</p>
          <div className="bg-slate-100 p-6 rounded-3xl mb-10">
            <span className="block text-sm font-bold text-slate-400 uppercase tracking-widest mb-1">Puntuación Final</span>
            <span className="text-5xl font-black text-indigo-600 tracking-tighter">{gameState.score}</span>
          </div>
          <button 
            onClick={() => {
              setGameState(prev => ({ ...prev, lives: 3, score: 0 }));
              setView(GameView.MENU);
            }}
            className="w-full py-6 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl text-2xl font-black shadow-[0_8px_0_rgb(49,46,129)] active:translate-y-2 active:shadow-none transition-all"
          >
            VOLVER AL MENÚ
          </button>
        </div>
      )}

      {view === GameView.EDITOR && (
        <Editor 
          onClose={() => setView(GameView.MENU)}
          onSave={(newLevel) => {
            setLevels(prev => [newLevel, ...prev]);
            setCurrentLevel(newLevel);
            setFoundWords([]);
            setErrorWords([]);
            setCleanedIndices([]);
            setGameState(prev => ({
              ...prev,
              time: newLevel.timeLimit,
              isPlaying: true,
              levelIndex: 0 // Play it immediately as if it's the first
            }));
            setView(GameView.PLAYING);
          }}
        />
      )}

      {/* Secret HUD info for Konami mode */}
      {view === GameView.EDITOR && (
        <div className="fixed bottom-4 left-4 bg-black/50 text-white p-2 rounded text-[10px] font-mono">
          KONAMI MODE ACTIVATED - EDITOR UNLOCKED
        </div>
      )}
    </div>
  );
};

export default App;

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GameView, GameState, WordClass, Level, WordData } from './types';
import { INITIAL_LEVELS, KONAMI_CODE } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';

const App: React.FC = () => {
  const [view, setView] = useState<GameView>(GameView.MENU);
  const [gameState, setGameState] = useState<GameState>({
    score: 0,
    lives: 3,
    time: 0,
    levelIndex: 0,
    isPlaying: false,
    isGameOver: false,
    powerups: { hints: 2, shields: 1, cleaners: 1 }
  });
  const [levels, setLevels] = useState<Level[]>(INITIAL_LEVELS);
  const [currentLevel, setCurrentLevel] = useState<Level | null>(null);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [errorWords, setErrorWords] = useState<string[]>([]);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [showKonamiEffect, setShowKonamiEffect] = useState(false);

  // Powerup effects
  const [highlightActive, setHighlightActive] = useState(false);
  const [cleanedIndices, setCleanedIndices] = useState<number[]>([]);

  // Fix: Use any instead of NodeJS.Timeout to avoid namespace errors in browser environments
  const timerRef = useRef<any>(null);

  const startGame = (index = 0) => {
    const level = levels[index];
    if (!level) return;

    // Process text into words if not already done
    let words = level.words;
    if (words.length === 0) {
      words = level.text.split(/\s+/).map((t, i) => ({
        text: t.replace(/[.,;:]/g, ''),
        category: WordClass.SUSTANTIVO, // Fallback dummy category
        id: `${i}-${Date.now()}`
      }));
    }

    setCurrentLevel({ ...level, words });
    setGameState(prev => ({
      ...prev,
      time: level.timeLimit,
      levelIndex: index,
      isPlaying: true,
      isGameOver: false
    }));
    setFoundWords([]);
    setErrorWords([]);
    setCleanedIndices([]);
    setHighlightActive(false);
    setView(GameView.PLAYING);
  };

  const handleGameOver = (win: boolean) => {
    if (timerRef.current) clearInterval(timerRef.current);
    setView(GameView.GAME_OVER);
    setGameState(prev => ({ ...prev, isPlaying: false, isGameOver: true }));
  };

  const nextLevel = () => {
    const nextIdx = gameState.levelIndex + 1;
    if (nextIdx < levels.length) {
      startGame(nextIdx);
    } else {
      alert("¡HAS GANADO TODO EL JUEGO!");
      setView(GameView.MENU);
    }
  };

  useEffect(() => {
    if (gameState.isPlaying && gameState.time > 0) {
      timerRef.current = setInterval(() => {
        setGameState(prev => {
          if (prev.time <= 1) {
            handleGameOver(false);
            return { ...prev, time: 0 };
          }
          return { ...prev, time: prev.time - 1 };
        });
      }, 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [gameState.isPlaying, gameState.levelIndex]);

  const handleWordClick = (word: WordData, index: number) => {
    if (!gameState.isPlaying || !currentLevel) return;
    if (foundWords.includes(word.id) || errorWords.includes(word.id)) return;

    if (word.category === currentLevel.targetCategory) {
      const newFound = [...foundWords, word.id];
      setFoundWords(newFound);
      setGameState(prev => ({ ...prev, score: prev.score + 10 }));

      // Check level completion
      const targetWordsCount = currentLevel.words.filter(w => w.category === currentLevel.targetCategory).length;
      if (newFound.length === targetWordsCount && targetWordsCount > 0) {
        setTimeout(() => nextLevel(), 1000);
      }
    } else {
      setErrorWords(prev => [...prev, word.id]);
      setGameState(prev => {
        const newLives = prev.lives - 1;
        if (newLives <= 0) {
          handleGameOver(false);
          return { ...prev, lives: 0, time: 0 };
        }
        return { ...prev, lives: newLives, time: Math.max(0, prev.time - 5) };
      });
    }
  };

  const useHint = () => {
    if (gameState.powerups.hints <= 0 || !currentLevel) return;
    const targets = currentLevel.words.filter(w => w.category === currentLevel.targetCategory && !foundWords.includes(w.id));
    if (targets.length > 0) {
      const random = targets[Math.floor(Math.random() * targets.length)];
      handleWordClick(random, currentLevel.words.indexOf(random));
      setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, hints: prev.powerups.hints - 1 } }));
    }
  };

  const useCleaner = () => {
    if (gameState.powerups.cleaners <= 0 || !currentLevel) return;
    const wrongOnes = currentLevel.words
      .map((w, i) => ({ w, i }))
      .filter(item => item.w.category !== currentLevel.targetCategory && !errorWords.includes(item.w.id) && !cleanedIndices.includes(item.i));

    const count = Math.min(3, wrongOnes.length);
    const toClean = [];
    for (let i = 0; i < count; i++) {
      const idx = Math.floor(Math.random() * wrongOnes.length);
      toClean.push(wrongOnes[idx].i);
      wrongOnes.splice(idx, 1);
    }
    setCleanedIndices(prev => [...prev, ...toClean]);
    setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, cleaners: prev.powerups.cleaners - 1 } }));
  };

  // Konami Code Detection
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const nextProgress = [...konamiProgress, e.key];
      const matchLength = nextProgress.length;
      const expected = KONAMI_CODE.slice(0, matchLength);

      if (JSON.stringify(nextProgress) === JSON.stringify(expected)) {
        if (matchLength === KONAMI_CODE.length) {
          setShowKonamiEffect(true);
          setView(GameView.EDITOR);
          setKonamiProgress([]);
        } else {
          setKonamiProgress(nextProgress);
        }
      } else {
        setKonamiProgress([]);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress]);

  return (
    <div className={`min-h-screen w-full flex flex-col items-center justify-center p-4 bg-gradient-to-br from-blue-400 via-indigo-400 to-purple-500 overflow-hidden transition-all duration-1000 ${showKonamiEffect ? 'konami-active' : ''}`}>

      {view === GameView.MENU && (
        <div className="text-center animate-in fade-in zoom-in duration-500">
          <div className="relative mb-8">
            <h1 className="text-8xl font-black text-white italic drop-shadow-[0_10px_10px_rgba(0,0,0,0.3)] tracking-tighter">
              GRAMMA<span className="text-yellow-300">CAT</span>
            </h1>
            <div className="absolute -top-12 -right-12 rotate-12 bg-white px-4 py-2 rounded-2xl shadow-lg border-4 border-indigo-600">
              <span className="text-2xl font-bold text-indigo-600">MEOW! 🐾</span>
            </div>
          </div>
          <p className="text-white/90 text-xl font-medium mb-12 max-w-md mx-auto leading-relaxed">
            Domina las categorías gramaticales en este desafío contrarreloj lleno de sorpresas.
          </p>
          <button 
            onClick={() => startGame(0)}
            className="group relative px-12 py-6 bg-yellow-400 hover:bg-yellow-300 text-indigo-900 rounded-3xl text-4xl font-black shadow-[0_12px_0_rgb(180,120,0)] hover:translate-y-1 hover:shadow-[0_8px_0_rgb(180,120,0)] transition-all active:translate-y-3 active:shadow-none"
          >
            ¡EMPEZAR A JUGAR!
            <i className="fas fa-play ml-4 text-3xl group-hover:translate-x-2 transition-transform"></i>
          </button>

          <div className="mt-16 flex justify-center space-x-12">
            <div className="flex flex-col items-center text-white">
              <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-2xl mb-2">
                <i className="fas fa-keyboard"></i>
              </div>
              <span className="text-xs font-bold uppercase tracking-widest">Aprende</span>
            </div>
            <div className="flex flex-col items-center text-white">
              <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-2xl mb-2">
                <i className="fas fa-bolt"></i>
              </div>
              <span className="text-xs font-bold uppercase tracking-widest">Velocidad</span>
            </div>
            <div className="flex flex-col items-center text-white">
              <div className="w-16 h-16 bg-white/20 rounded-2xl flex items-center justify-center text-2xl mb-2">
                <i className="fas fa-trophy"></i>
              </div>
              <span className="text-xs font-bold uppercase tracking-widest">Ranking</span>
            </div>
          </div>
        </div>
      )}

      {view === GameView.PLAYING && currentLevel && (
        <div className="w-full flex flex-col items-center animate-in slide-in-from-bottom duration-500">
          <GameHUD state={gameState} target={currentLevel.targetCategory} />

          <div className="w-full max-w-4xl bg-white/90 backdrop-blur-md rounded-[3rem] p-12 shadow-2xl border-b-8 border-indigo-200 min-h-[400px] flex flex-col justify-center relative overflow-hidden">
            {/* Background pattern */}
            <div className="absolute inset-0 opacity-5 pointer-events-none">
                <div className="absolute top-0 left-0 w-full h-full" style={{backgroundImage: 'radial-gradient(#4f46e5 1px, transparent 1px)', backgroundSize: '24px 24px'}}></div>
            </div>

            <div className="relative z-10 flex flex-wrap justify-center items-center gap-x-2 gap-y-4 text-4xl font-semibold leading-relaxed tracking-tight text-slate-800">
              {currentLevel.words.map((w, i) => {
                const isFound = foundWords.includes(w.id);
                const isError = errorWords.includes(w.id);
                const isCleaned = cleanedIndices.includes(i);

                return (
                  <span 
                    key={w.id}
                    onClick={() => handleWordClick(w, i)}
                    className={`
                      cursor-pointer px-4 py-2 rounded-2xl transition-all duration-300 transform hover:scale-110 active:scale-95 select-none
                      ${isFound ? 'bg-green-400 text-white shadow-lg -rotate-2 scale-105 pointer-events-none' : ''}
                      ${isError ? 'bg-rose-400 text-white shadow-lg rotate-2 scale-105 pointer-events-none line-through opacity-50' : ''}
                      ${isCleaned ? 'opacity-20 line-through scale-90 pointer-events-none filter grayscale' : ''}
                      ${!isFound && !isError && !isCleaned ? 'hover:bg-indigo-100 hover:text-indigo-600' : ''}
                    `}
                  >
                    {w.text}
                  </span>
                );
              })}
            </div>
          </div>

          <div className="w-full max-w-4xl mt-8 flex justify-center space-x-6">
            <button 
              onClick={useHint}
              disabled={gameState.powerups.hints <= 0}
              className={`flex flex-col items-center p-4 rounded-3xl transition-all ${gameState.powerups.hints > 0 ? 'bg-amber-400 text-amber-900 shadow-lg hover:translate-y-1' : 'bg-slate-200 text-slate-400 opacity-50'}`}
            >
              <i className="fas fa-lightbulb text-3xl mb-1"></i>
              <span className="text-[10px] font-black uppercase">Pista ({gameState.powerups.hints})</span>
            </button>

            <button 
              onClick={useCleaner}
              disabled={gameState.powerups.cleaners <= 0}
              className={`flex flex-col items-center p-4 rounded-3xl transition-all ${gameState.powerups.cleaners > 0 ? 'bg-cyan-400 text-cyan-900 shadow-lg hover:translate-y-1' : 'bg-slate-200 text-slate-400 opacity-50'}`}
            >
              <i className="fas fa-broom text-3xl mb-1"></i>
              <span className="text-[10px] font-black uppercase">Limpiar ({gameState.powerups.cleaners})</span>
            </button>

            <button 
              className="flex flex-col items-center p-4 rounded-3xl bg-indigo-500 text-white shadow-lg opacity-50 cursor-not-allowed"
            >
              <i className="fas fa-shield-alt text-3xl mb-1"></i>
              <span className="text-[10px] font-black uppercase">Escudo (0)</span>
            </button>
          </div>
        </div>
      )}

      {view === GameView.GAME_OVER && (
        <div className="text-center bg-white p-12 rounded-[3rem] shadow-2xl border-8 border-rose-500 animate-in zoom-in duration-300">
          <i className="fas fa-skull-crossbones text-7xl text-rose-500 mb-6"></i>
          <h2 className="text-6xl font-black text-slate-900 italic tracking-tighter mb-4">GAME OVER</h2>
          <p className="text-2xl font-bold text-slate-500 mb-8">¡Pero no te rindas! ¡El conocimiento es poder!</p>
          <div className="bg-slate-100 p-6 rounded-3xl mb-10">
            <span className="block text-sm font-bold text-slate-400 uppercase tracking-widest mb-1">Puntuación Final</span>
            <span className="text-5xl font-black text-indigo-600 tracking-tighter">{gameState.score}</span>
          </div>
          <button 
            onClick={() => {
              setGameState(prev => ({ ...prev, lives: 3, score: 0 }));
              setView(GameView.MENU);
            }}
            className="w-full py-6 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl text-2xl font-black shadow-[0_8px_0_rgb(49,46,129)] active:translate-y-2 active:shadow-none transition-all"
          >
            VOLVER AL MENÚ
          </button>
        </div>
      )}

      {view === GameView.EDITOR && (
        <Editor 
          onClose={() => setView(GameView.MENU)}
          onSave={(newLevel) => {
            setLevels(prev => [newLevel, ...prev]);
            setCurrentLevel(newLevel);
            setFoundWords([]);
            setErrorWords([]);
            setCleanedIndices([]);
            setGameState(prev => ({
              ...prev,
              time: newLevel.timeLimit,
              isPlaying: true,
              levelIndex: 0 // Play it immediately as if it's the first
            }));
            setView(GameView.PLAYING);
          }}
        />
      )}

      {/* Secret HUD info for Konami mode */}
      {view === GameView.EDITOR && (
        <div className="fixed bottom-4 left-4 bg-black/50 text-white p-2 rounded text-[10px] font-mono">
          KONAMI MODE ACTIVATED - EDITOR UNLOCKED
        </div>
      )}
    </div>
  );
};

