import { createClient } from '@supabase/supabase-js';
import { Level } from '../types';

// Asumimos que las variables están disponibles en el entorno.
// Si no están configuradas, el servicio fallará silenciosamente o usará localStorage.
const supabaseUrl = (process.env as any).SUPABASE_URL || '';
const supabaseKey = (process.env as any).SUPABASE_ANON_KEY || '';

export const supabase = (supabaseUrl && supabaseKey) 
  ? createClient(supabaseUrl, supabaseKey) 
  : null;

export const saveLevelOnline = async (level: Level) => {
  if (!supabase) return { error: 'Supabase no configurado' };

  const { data, error } = await supabase
    .from('levels')
    .insert([{
      title: level.title,
      text: level.text,
      target_category: level.targetCategory,
      words: level.words,
      time_limit: level.timeLimit
    }]);

  return { data, error };
};

export const fetchCommunityLevels = async (): Promise<Level[]> => {
  if (!supabase) return [];

  const { data, error } = await supabase
    .from('levels')
    .select('*')
    .order('created_at', { ascending: false });

  if (error) {
    console.error("Error fetching levels:", error);
    return [];
  }

  return data.map(d => ({
    id: d.id,
    title: d.title,
    text: d.text,
    targetCategory: d.target_category,
    words: d.words,
    timeLimit: d.time_limit
  }));
};

import React, { useState } from 'react';
import { WordClass, Level, WordData } from '../types';
import { analyzeTextWithAI } from '../services/geminiService';
import { saveLevelOnline, supabase } from '../services/supabaseService';

interface Props {
  onSave: (level: Level) => void;
  onClose: () => void;
}

export const Editor: React.FC<Props> = ({ onSave, onClose }) => {
  const [text, setText] = useState('');
  const [title, setTitle] = useState('');
  const [targetCategory, setTargetCategory] = useState<WordClass>(WordClass.SUSTANTIVO);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [analyzedWords, setAnalyzedWords] = useState<WordData[]>([]);

  const handleAnalyze = async () => {
    if (!text.trim()) return;
    setIsAnalyzing(true);
    const result = await analyzeTextWithAI(text);
    const formatted = result.map((w: any, idx: number) => ({
      ...w,
      id: `custom-${idx}-${Date.now()}`
    }));
    setAnalyzedWords(formatted);
    setIsAnalyzing(false);
  };

  const handleSave = async (online: boolean) => {
    if (analyzedWords.length === 0) {
      alert("Primero debes analizar el texto para identificar las categorías.");
      return;
    }

    const newLevel: Level = {
      id: Date.now(),
      title: title || "Nivel Personalizado",
      text,
      targetCategory,
      words: analyzedWords,
      timeLimit: 30
    };

    if (online) {
      if (!supabase) {
        alert("Configuración de Supabase no encontrada. Guardando localmente...");
        onSave(newLevel);
        return;
      }
      setIsSaving(true);
      const { error } = await saveLevelOnline(newLevel);
      setIsSaving(false);
      if (error) {
        alert("Error al guardar online: " + (error as any).message);
      } else {
        alert("¡Nivel guardado en la nube!");
      }
    }

    onSave(newLevel);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-indigo-950/80 backdrop-blur-md p-4">
      <div className="bg-white w-full max-w-4xl rounded-3xl overflow-hidden flex flex-col max-h-[90vh] shadow-2xl border-8 border-indigo-400">
        <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
          <h2 className="text-3xl font-black italic tracking-tighter">EDITOR SECRETO <span className="text-yellow-400">GEMINI IA</span></h2>
          <button onClick={onClose} className="hover:bg-indigo-700 p-2 rounded-full transition-colors">
            <i className="fas fa-times text-2xl"></i>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-400 uppercase">Título del Nivel</label>
              <input value={title} onChange={e => setTitle(e.target.value)} className="w-full p-4 rounded-xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-bold" placeholder="Ej: El misterio de las letras..." />
            </div>
            <div className="space-y-2">
              <label className="text-xs font-bold text-indigo-400 uppercase">Categoría Objetivo</label>
              <select value={targetCategory} onChange={e => setTargetCategory(e.target.value as WordClass)} className="w-full p-4 rounded-xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-bold">
                {Object.values(WordClass).map(cat => <option key={cat} value={cat}>{cat}</option>)}
              </select>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-400 uppercase">Texto a Analizar</label>
            <textarea value={text} onChange={e => setText(e.target.value)} className="w-full h-32 p-4 rounded-xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-medium text-lg leading-relaxed" placeholder="Pega tu texto aquí..." />
          </div>

          <button onClick={handleAnalyze} disabled={isAnalyzing || !text} className={`w-full py-4 rounded-2xl text-white font-black text-xl shadow-lg transition-all ${isAnalyzing ? 'bg-gray-400' : 'bg-gradient-to-r from-indigo-500 to-purple-500 hover:scale-[1.02] active:scale-95'}`}>
            {isAnalyzing ? <><i className="fas fa-spinner fa-spin mr-2"></i>ANALIZANDO...</> : 'ANALIZAR CON INTELIGENCIA ARTIFICIAL'}
          </button>

          {analyzedWords.length > 0 && (
            <div className="p-6 bg-slate-50 rounded-2xl border-2 border-slate-200">
              <h3 className="text-sm font-bold text-slate-500 uppercase mb-4 text-center">Revisión de Clases IA:</h3>
              <div className="flex flex-wrap gap-2 justify-center">
                {analyzedWords.map((w, i) => (
                  <div key={i} className="bg-white px-3 py-1 rounded-lg border border-slate-300 flex items-center shadow-sm">
                    <span className="font-medium mr-2">{w.text}</span>
                    <span className="text-[9px] px-1.5 py-0.5 bg-indigo-100 text-indigo-600 rounded font-bold uppercase">{w.category}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="p-6 bg-slate-100 border-t flex flex-col sm:flex-row gap-4 justify-between">
           <p className="text-xs font-bold text-slate-400 self-center">Recuerda: El guardado online requiere configuración previa de Supabase.</p>
           <div className="flex gap-4">
              <button onClick={() => handleSave(false)} className="px-6 py-3 bg-slate-600 hover:bg-slate-700 text-white font-black rounded-xl shadow-lg transition-all active:scale-95">SOLO LOCAL</button>
              <button onClick={() => handleSave(true)} disabled={isSaving} className="px-8 py-3 bg-green-500 hover:bg-green-600 text-white font-black rounded-xl shadow-lg transition-all active:scale-95 flex items-center">
                {isSaving ? <i className="fas fa-spinner fa-spin mr-2"></i> : <i className="fas fa-cloud-upload-alt mr-2"></i>}
                GUARDAR ONLINE
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GameView, GameState, WordClass, Level, WordData, Achievement } from './types';
import { INITIAL_LEVELS, KONAMI_CODE, INITIAL_ACHIEVEMENTS } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';
import { AchievementsModal } from './components/AchievementsModal';
import { fetchCommunityLevels } from './services/supabaseService';

const App: React.FC = () => {
  const [view, setView] = useState<GameView>(GameView.MENU);
  const [gameState, setGameState] = useState<GameState>(() => {
    const savedStats = localStorage.getItem('grammaticat_stats');
    const stats = savedStats ? JSON.parse(savedStats) : { nounsFound: 0, levelsCompleted: 0 };
    return {
      score: 0,
      lives: 3,
      time: 0,
      levelIndex: 0,
      isPlaying: false,
      isGameOver: false,
      powerups: { hints: 2, shields: 1, cleaners: 1 },
      stats
    };
  });

  const [levels, setLevels] = useState<Level[]>(INITIAL_LEVELS);
  const [communityLevels, setCommunityLevels] = useState<Level[]>([]);
  const [isLoadingCommunity, setIsLoadingCommunity] = useState(false);
  const [currentLevel, setCurrentLevel] = useState<Level | null>(null);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [errorWords, setErrorWords] = useState<string[]>([]);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [showKonamiEffect, setShowKonamiEffect] = useState(false);
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('grammaticat_achievements');
    return saved ? JSON.parse(saved) : INITIAL_ACHIEVEMENTS;
  });

  const [lastUnlocked, setLastUnlocked] = useState<Achievement | null>(null);
  const timerRef = useRef<any>(null);

  useEffect(() => {
    const loadCommunity = async () => {
      setIsLoadingCommunity(true);
      const onlineLevels = await fetchCommunityLevels();
      setCommunityLevels(onlineLevels);
      setIsLoadingCommunity(false);
    };
    loadCommunity();
  }, []);

  useEffect(() => {
    localStorage.setItem('grammaticat_achievements', JSON.stringify(achievements));
  }, [achievements]);

  useEffect(() => {
    localStorage.setItem('grammaticat_stats', JSON.stringify(gameState.stats));
  }, [gameState.stats]);

  const unlockAchievement = (id: string) => {
    setAchievements(prev => {
      const ach = prev.find(a => a.id === id);
      if (ach && !ach.unlocked) {
        const updated = prev.map(a => a.id === id ? { ...a, unlocked: true, unlockedAt: Date.now() } : a);
        setLastUnlocked({ ...ach, unlocked: true });
        setTimeout(() => setLastUnlocked(null), 4000);
        return updated;
      }
      return prev;
    });
  };

  const updateAchievementProgress = (id: string, increment: number) => {
    setAchievements(prev => {
      return prev.map(a => {
        if (a.id === id && !a.unlocked && a.goal) {
          const newProgress = (a.progress || 0) + increment;
          if (newProgress >= a.goal) {
            unlockAchievement(id);
            return { ...a, progress: a.goal, unlocked: true, unlockedAt: Date.now() };
          }
          return { ...a, progress: newProgress };
        }
        return a;
      });
    });
  };

  const startGame = (level: Level, index: number) => {
    // Si el nivel no tiene palabras categorizadas, usamos el fallback (aunque ahora INITIAL_LEVELS sí tiene)
    let words = level.words && level.words.length > 0 ? level.words : level.text.split(/\s+/).map((t, i) => ({
      text: t.replace(/[.,;:]/g, ''),
      category: WordClass.SUSTANTIVO,
      id: `${i}-${Date.now()}`
    }));

    setCurrentLevel({ ...level, words });
    setGameState(prev => ({
      ...prev,
      time: level.timeLimit,
      levelIndex: index,
      isPlaying: true,
      isGameOver: false
    }));
    setFoundWords([]);
    setErrorWords([]);
    setView(GameView.PLAYING);
  };

  const handleGameOver = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setView(GameView.GAME_OVER);
    setGameState(prev => ({ ...prev, isPlaying: false, isGameOver: true }));
  };

  useEffect(() => {
    if (gameState.isPlaying && gameState.time > 0) {
      timerRef.current = setInterval(() => {
        setGameState(prev => {
          if (prev.time <= 1) {
            handleGameOver();
            return { ...prev, time: 0 };
          }
          return { ...prev, time: prev.time - 1 };
        });
      }, 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [gameState.isPlaying]);

  const handleWordClick = (word: WordData, index: number) => {
    if (!gameState.isPlaying || !currentLevel) return;
    if (foundWords.includes(word.id) || errorWords.includes(word.id)) return;

    if (word.category === currentLevel.targetCategory) {
      const newFound = [...foundWords, word.id];
      setFoundWords(newFound);

      if (word.category === WordClass.SUSTANTIVO) {
        setGameState(prev => ({ ...prev, stats: { ...prev.stats, nounsFound: prev.stats.nounsFound + 1 } }));
        updateAchievementProgress('noun_expert', 1);
      }

      setGameState(prev => ({ ...prev, score: prev.score + 10 }));

      const targetWordsCount = currentLevel.words.filter(w => w.category === currentLevel.targetCategory).length;
      if (newFound.length === targetWordsCount && targetWordsCount > 0) {
        // Achievement: First steps
        unlockAchievement('first_steps');
        // Achievement: Speedster
        if (gameState.time > (currentLevel.timeLimit / 2)) {
          unlockAchievement('speedster');
        }

        setTimeout(() => setView(GameView.MENU), 1500);
      }
    } else {
      setErrorWords(prev => [...prev, word.id]);
      setGameState(prev => {
        const newLives = prev.lives - 1;
        if (newLives <= 0) {
          handleGameOver();
          return { ...prev, lives: 0, time: 0 };
        }
        return { ...prev, lives: newLives, time: Math.max(0, prev.time - 5) };
      });
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const nextProgress = [...konamiProgress, e.key];
      const matchLength = nextProgress.length;
      const expected = KONAMI_CODE.slice(0, matchLength);

      if (JSON.stringify(nextProgress) === JSON.stringify(expected)) {
        if (matchLength === KONAMI_CODE.length) {
          unlockAchievement('hidden_discoverer');
          setShowKonamiEffect(true);
          setView(GameView.EDITOR);
          setKonamiProgress([]);
        } else {
          setKonamiProgress(nextProgress);
        }
      } else {
        setKonamiProgress([]);
      }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress]);

  return (
    <div className={`min-h-screen w-full flex flex-col items-center justify-center p-4 bg-gradient-to-br from-blue-400 via-indigo-400 to-purple-500 overflow-hidden transition-all duration-1000 ${showKonamiEffect ? 'konami-active' : ''}`}>

      {lastUnlocked && (
        <div className="fixed top-8 right-8 z-[100] bg-white p-4 rounded-2xl shadow-2xl border-4 border-yellow-400 animate-in slide-in-from-right duration-500 flex items-center space-x-4">
          <div className="w-12 h-12 bg-yellow-400 rounded-xl flex items-center justify-center text-indigo-900 text-xl">
            <i className={`fas ${lastUnlocked.icon}`}></i>
          </div>
          <div>
            <span className="block text-[10px] font-black text-yellow-600 uppercase tracking-widest">¡Logro Desbloqueado!</span>
            <span className="block text-lg font-black text-indigo-900">{lastUnlocked.title}</span>
          </div>
        </div>
      )}

      {view === GameView.MENU && (
        <div className="w-full max-w-5xl flex flex-col items-center animate-in fade-in zoom-in duration-500 overflow-y-auto max-h-screen py-12 px-4">
          <div className="relative mb-8 text-center">
            <h1 className="text-8xl font-black text-white italic drop-shadow-[0_10px_10px_rgba(0,0,0,0.3)] tracking-tighter">
              GRAMMA<span className="text-yellow-300">CAT</span>
            </h1>
            <p className="text-white/90 text-xl font-medium mt-4">Domina las categorías gramaticales.</p>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full">
            {/* Niveles Base */}
            <div className="bg-white/20 backdrop-blur-md p-6 rounded-[2rem] border-2 border-white/20">
               <h2 className="text-2xl font-black text-white mb-4 uppercase tracking-tighter flex items-center">
                  <i className="fas fa-play-circle mr-3"></i> Campaña Original
               </h2>
               <div className="space-y-3">
                  {levels.map((lvl, idx) => (
                    <button key={lvl.id} onClick={() => startGame(lvl, idx)} className="w-full p-4 bg-white rounded-2xl flex justify-between items-center hover:scale-[1.02] transition-all shadow-lg border-b-4 border-indigo-200">
                       <span className="font-bold text-indigo-900 text-lg">{lvl.title}</span>
                       <span className="px-3 py-1 bg-yellow-400 text-indigo-900 rounded-full text-xs font-black uppercase">{lvl.targetCategory}s</span>
                    </button>
                  ))}
               </div>
            </div>

            {/* Niveles Comunidad */}
            <div className="bg-indigo-900/30 backdrop-blur-md p-6 rounded-[2rem] border-2 border-indigo-400/20">
               <h2 className="text-2xl font-black text-yellow-300 mb-4 uppercase tracking-tighter flex items-center">
                  <i className="fas fa-users mr-3"></i> Comunidad Online
               </h2>
               {isLoadingCommunity ? (
                 <div className="text-white text-center py-8"><i className="fas fa-spinner fa-spin mr-2"></i> Cargando...</div>
               ) : communityLevels.length === 0 ? (
                 <div className="text-indigo-200 text-center py-8 text-sm italic">No hay niveles online disponibles.</div>
               ) : (
                 <div className="space-y-3 max-h-64 overflow-y-auto pr-2 custom-scrollbar">
                    {communityLevels.map((lvl, idx) => (
                      <button key={lvl.id} onClick={() => startGame(lvl, idx)} className="w-full p-4 bg-indigo-500/50 hover:bg-indigo-500 rounded-2xl flex justify-between items-center transition-all border border-indigo-400/30">
                         <span className="font-bold text-white">{lvl.title}</span>
                         <span className="px-3 py-1 bg-white text-indigo-900 rounded-full text-[10px] font-black uppercase">{lvl.targetCategory}</span>
                      </button>
                    ))}
                 </div>
               )}
            </div>
          </div>

          <div className="mt-12 flex space-x-6">
            <button onClick={() => setView(GameView.ACHIEVEMENTS)} className="px-8 py-4 bg-white text-indigo-600 rounded-3xl text-2xl font-black shadow-xl hover:translate-y-1 transition-all flex items-center">
              <i className="fas fa-trophy mr-3"></i> TROFEOS
            </button>
          </div>
        </div>
      )}

      {view === GameView.ACHIEVEMENTS && <AchievementsModal achievements={achievements} onClose={() => setView(GameView.MENU)} />}

      {view === GameView.PLAYING && currentLevel && (
        <div className="w-full flex flex-col items-center animate-in slide-in-from-bottom duration-500">
          <GameHUD state={gameState} target={currentLevel.targetCategory} />
          <div className="w-full max-w-4xl bg-white/95 backdrop-blur-md rounded-[4rem] p-16 shadow-2xl border-b-8 border-indigo-200 min-h-[450px] flex flex-col justify-center relative">
            <div className="relative z-10 flex flex-wrap justify-center items-center gap-x-4 gap-y-6 text-5xl font-semibold text-slate-800">
              {currentLevel.words.map((w, i) => (
                <span key={w.id} onClick={() => handleWordClick(w, i)} className={`cursor-pointer px-5 py-2 rounded-3xl transition-all duration-300 transform hover:scale-110 active:scale-95 select-none
                    ${foundWords.includes(w.id) ? 'bg-green-500 text-white shadow-[0_6px_0_rgb(22,163,74)] -rotate-3 scale-110' : ''}
                    ${errorWords.includes(w.id) ? 'bg-rose-500 text-white shadow-lg rotate-3 scale-110 opacity-50' : ''}
                    ${!foundWords.includes(w.id) && !errorWords.includes(w.id) ? 'hover:bg-indigo-50 text-indigo-700' : ''}
                  `}>
                  {w.text}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {view === GameView.GAME_OVER && (
        <div className="text-center bg-white p-12 rounded-[3rem] shadow-2xl border-8 border-rose-500 animate-in zoom-in duration-300">
          <h2 className="text-6xl font-black text-slate-900 italic tracking-tighter mb-4">GAME OVER</h2>
          <button onClick={() => setView(GameView.MENU)} className="w-full py-6 bg-indigo-600 text-white rounded-2xl text-2xl font-black">VOLVER AL MENÚ</button>
        </div>
      )}

      {view === GameView.EDITOR && (
        <Editor onClose={() => setView(GameView.MENU)} onSave={(newLevel) => {
          setLevels(prev => [newLevel, ...prev]);
          startGame(newLevel, 0);
        }} />
      )}
    </div>
  );
};

export default App;

export enum WordClass {
  SUSTANTIVO = 'Sustantivo',
  ADJETIVO = 'Adjetivo',
  VERBO = 'Verbo',
  ADVERBIO = 'Adverbio',
  PRONOMBRE = 'Pronombre',
  PREPOSICION = 'Preposición',
  CONJUNCION = 'Conjunción',
  DETERMINANTE = 'Determinante'
}

export interface WordData {
  text: string;
  category: WordClass;
  id: string;
}

export interface Level {
  id: number;
  title: string;
  text: string;
  words: WordData[];
  timeLimit: number;
  targetCategory?: WordClass; // Ahora es opcional o dinámico
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: string;
  unlocked: boolean;
  unlockedAt?: number;
  progress?: number;
  goal?: number;
}

export interface GameState {
  score: number;
  lives: number;
  time: number;
  levelIndex: number;
  isPlaying: boolean;
  isGameOver: boolean;
  targetCategory: WordClass | null;
  powerups: {
    hints: number;
    shields: number;
    cleaners: number;
  };
  stats: {
    nounsFound: number;
    levelsCompleted: number;
  };
}

export enum GameView {
  MENU = 'MENU',
  PLAYING = 'PLAYING',
  EDITOR = 'EDITOR',
  GAME_OVER = 'GAME_OVER',
  ACHIEVEMENTS = 'ACHIEVEMENTS'
}

import React, { useState } from 'react';
import { WordClass, Level, WordData } from '../types';
import { analyzeTextWithAI } from '../services/geminiService';
import { saveLevelOnline, supabase } from '../services/supabaseService';

interface Props {
  onSave: (level: Level) => void;
  onClose: () => void;
}

export const Editor: React.FC<Props> = ({ onSave, onClose }) => {
  const [text, setText] = useState('');
  const [title, setTitle] = useState('');
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [analyzedWords, setAnalyzedWords] = useState<WordData[]>([]);

  const handleAnalyze = async () => {
    if (!text.trim()) return;
    setIsAnalyzing(true);
    const result = await analyzeTextWithAI(text);
    const formatted = result.map((w: any, idx: number) => ({
      ...w,
      id: `custom-${idx}-${Date.now()}`
    }));
    setAnalyzedWords(formatted);
    setIsAnalyzing(false);
  };

  const handleSave = async (online: boolean) => {
    if (analyzedWords.length === 0) {
      alert("Primero debes analizar el texto para identificar las categorías.");
      return;
    }

    const newLevel: Level = {
      id: Date.now(),
      title: title || "Nivel Personalizado",
      text,
      words: analyzedWords,
      timeLimit: 30
    };

    if (online) {
      if (!supabase) {
        alert("Configuración de Supabase no encontrada. Guardando localmente...");
        onSave(newLevel);
        return;
      }
      setIsSaving(true);
      const { error } = await saveLevelOnline(newLevel);
      setIsSaving(false);
      if (error) {
        alert("Error al guardar online: " + (error as any).message);
      } else {
        alert("¡Nivel guardado en la nube! Ahora disponible para cualquier categoría.");
      }
    }

    onSave(newLevel);
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-indigo-950/80 backdrop-blur-md p-4">
      <div className="bg-white w-full max-w-4xl rounded-3xl overflow-hidden flex flex-col max-h-[90vh] shadow-2xl border-8 border-indigo-400">
        <div className="p-6 bg-indigo-600 text-white flex justify-between items-center">
          <h2 className="text-3xl font-black italic tracking-tighter">EDITOR <span className="text-yellow-400">UNIVERSAL</span></h2>
          <button onClick={onClose} className="hover:bg-indigo-700 p-2 rounded-full transition-colors">
            <i className="fas fa-times text-2xl"></i>
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-8 space-y-6">
          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-400 uppercase tracking-widest">Nombre del Nivel</label>
            <input value={title} onChange={e => setTitle(e.target.value)} className="w-full p-4 rounded-xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-bold text-xl" placeholder="Ej: La leyenda del dragón..." />
          </div>

          <div className="space-y-2">
            <label className="text-xs font-bold text-indigo-400 uppercase tracking-widest">Cuerpo del Texto</label>
            <textarea value={text} onChange={e => setText(e.target.value)} className="w-full h-40 p-6 rounded-2xl bg-indigo-50 border-2 border-indigo-100 focus:border-indigo-400 outline-none font-medium text-lg leading-relaxed shadow-inner" placeholder="Escribe o pega aquí el texto que quieras convertir en juego..." />
          </div>

          <button onClick={handleAnalyze} disabled={isAnalyzing || !text} className={`w-full py-5 rounded-2xl text-white font-black text-2xl shadow-xl transition-all ${isAnalyzing ? 'bg-gray-400' : 'bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 hover:scale-[1.01] active:scale-95'}`}>
            {isAnalyzing ? <><i className="fas fa-spinner fa-spin mr-3"></i>ESCANEANDO GRAMÁTICA...</> : 'ANALIZAR CON INTELIGENCIA ARTIFICIAL'}
          </button>

          {analyzedWords.length > 0 && (
            <div className="p-6 bg-green-50 rounded-3xl border-2 border-green-100">
              <h3 className="text-sm font-bold text-green-600 uppercase mb-4 text-center tracking-widest">¡Análisis Completado! Texto listo para jugar todas las categorías.</h3>
              <div className="flex flex-wrap gap-2 justify-center max-h-48 overflow-y-auto p-2">
                {analyzedWords.map((w, i) => (
                  <div key={i} className="bg-white px-3 py-1.5 rounded-xl border border-green-200 flex items-center shadow-sm">
                    <span className="font-bold text-slate-700 mr-2">{w.text}</span>
                    <span className="text-[8px] px-2 py-0.5 bg-green-100 text-green-700 rounded-full font-black uppercase">{w.category}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>

        <div className="p-8 bg-slate-50 border-t flex flex-col sm:flex-row gap-4 items-center justify-between">
           <div className="flex items-center text-slate-400 italic text-sm">
             <i className="fas fa-info-circle mr-2"></i>
             Un solo texto permitirá jugar retos de sustantivos, verbos, etc.
           </div>
           <div className="flex gap-4">
              <button onClick={() => handleSave(false)} className="px-8 py-4 bg-slate-600 hover:bg-slate-700 text-white font-black rounded-2xl shadow-lg transition-all active:scale-95">LOCAL</button>
              <button onClick={() => handleSave(true)} disabled={isSaving} className="px-10 py-4 bg-indigo-600 hover:bg-indigo-500 text-white font-black rounded-2xl shadow-lg transition-all active:scale-95 flex items-center">
                {isSaving ? <i className="fas fa-spinner fa-spin mr-2"></i> : <i className="fas fa-cloud-upload-alt mr-2"></i>}
                PUBLICAR ONLINE
              </button>
           </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GameView, GameState, WordClass, Level, WordData, Achievement } from './types';
import { INITIAL_LEVELS, KONAMI_CODE, INITIAL_ACHIEVEMENTS } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';
import { AchievementsModal } from './components/AchievementsModal';
import { fetchCommunityLevels } from './services/supabaseService';

const App: React.FC = () => {
  const [view, setView] = useState<GameView>(GameView.MENU);
  const [gameState, setGameState] = useState<GameState>(() => {
    const savedStats = localStorage.getItem('grammaticat_stats');
    const stats = savedStats ? JSON.parse(savedStats) : { nounsFound: 0, levelsCompleted: 0 };
    return {
      score: 0,
      lives: 3,
      time: 0,
      levelIndex: 0,
      isPlaying: false,
      isGameOver: false,
      targetCategory: null,
      powerups: { hints: 2, shields: 1, cleaners: 1 },
      stats
    };
  });

  const [levels, setLevels] = useState<Level[]>(INITIAL_LEVELS);
  const [communityLevels, setCommunityLevels] = useState<Level[]>([]);
  const [isLoadingCommunity, setIsLoadingCommunity] = useState(false);
  const [currentLevel, setCurrentLevel] = useState<Level | null>(null);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [errorWords, setErrorWords] = useState<string[]>([]);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [showKonamiEffect, setShowKonamiEffect] = useState(false);
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('grammaticat_achievements');
    return saved ? JSON.parse(saved) : INITIAL_ACHIEVEMENTS;
  });

  const [lastUnlocked, setLastUnlocked] = useState<Achievement | null>(null);
  const timerRef = useRef<any>(null);

  useEffect(() => {
    const loadCommunity = async () => {
      setIsLoadingCommunity(true);
      const onlineLevels = await fetchCommunityLevels();
      setCommunityLevels(onlineLevels);
      setIsLoadingCommunity(false);
    };
    loadCommunity();
  }, []);

  const unlockAchievement = (id: string) => {
    setAchievements(prev => {
      const ach = prev.find(a => a.id === id);
      if (ach && !ach.unlocked) {
        const updated = prev.map(a => a.id === id ? { ...a, unlocked: true, unlockedAt: Date.now() } : a);
        setLastUnlocked({ ...ach, unlocked: true });
        setTimeout(() => setLastUnlocked(null), 4000);
        return updated;
      }
      return prev;
    });
  };

  const updateAchievementProgress = (id: string, increment: number) => {
    setAchievements(prev => {
      return prev.map(a => {
        if (a.id === id && !a.unlocked && a.goal) {
          const newProgress = (a.progress || 0) + increment;
          if (newProgress >= a.goal) {
            unlockAchievement(id);
            return { ...a, progress: a.goal, unlocked: true, unlockedAt: Date.now() };
          }
          return { ...a, progress: newProgress };
        }
        return a;
      });
    });
  };

  const startGame = (level: Level, category: WordClass) => {
    const words = level.words && level.words.length > 0 ? level.words : [];

    setCurrentLevel({ ...level, words });
    setGameState(prev => ({
      ...prev,
      time: level.timeLimit || 30,
      targetCategory: category,
      isPlaying: true,
      isGameOver: false
    }));
    setFoundWords([]);
    setErrorWords([]);
    setView(GameView.PLAYING);
  };

  const handleGameOver = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setView(GameView.GAME_OVER);
    setGameState(prev => ({ ...prev, isPlaying: false, isGameOver: true }));
  };

  useEffect(() => {
    if (gameState.isPlaying && gameState.time > 0) {
      timerRef.current = setInterval(() => {
        setGameState(prev => {
          if (prev.time <= 1) {
            handleGameOver();
            return { ...prev, time: 0 };
          }
          return { ...prev, time: prev.time - 1 };
        });
      }, 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [gameState.isPlaying]);

  const handleWordClick = (word: WordData) => {
    if (!gameState.isPlaying || !currentLevel || !gameState.targetCategory) return;
    if (foundWords.includes(word.id) || errorWords.includes(word.id)) return;

    if (word.category === gameState.targetCategory) {
      const newFound = [...foundWords, word.id];
      setFoundWords(newFound);

      if (word.category === WordClass.SUSTANTIVO) {
        setGameState(prev => ({ ...prev, stats: { ...prev.stats, nounsFound: prev.stats.nounsFound + 1 } }));
        updateAchievementProgress('noun_expert', 1);
      }

      setGameState(prev => ({ ...prev, score: prev.score + 10 }));

      const targetWordsCount = currentLevel.words.filter(w => w.category === gameState.targetCategory).length;
      if (newFound.length === targetWordsCount && targetWordsCount > 0) {
        unlockAchievement('first_steps');
        if (gameState.time > (currentLevel.timeLimit / 2)) unlockAchievement('speedster');
        setTimeout(() => setView(GameView.MENU), 1500);
      }
    } else {
      setErrorWords(prev => [...prev, word.id]);
      setGameState(prev => {
        const newLives = prev.lives - 1;
        if (newLives <= 0) {
          handleGameOver();
          return { ...prev, lives: 0, time: 0 };
        }
        return { ...prev, lives: newLives, time: Math.max(0, prev.time - 5) };
      });
    }
  };

  const getAvailableCategories = (level: Level): WordClass[] => {
    const cats = new Set<WordClass>();
    level.words.forEach(w => cats.add(w.category));
    return Array.from(cats);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const nextProgress = [...konamiProgress, e.key];
      const matchLength = nextProgress.length;
      const expected = KONAMI_CODE.slice(0, matchLength);
      if (JSON.stringify(nextProgress) === JSON.stringify(expected)) {
        if (matchLength === KONAMI_CODE.length) {
          unlockAchievement('hidden_discoverer');
          setShowKonamiEffect(true);
          setView(GameView.EDITOR);
          setKonamiProgress([]);
        } else { setKonamiProgress(nextProgress); }
      } else { setKonamiProgress([]); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress]);

  const LevelCard = ({ level }: { level: Level }) => {
    const available = getAvailableCategories(level);
    return (
      <div className="bg-white rounded-3xl p-6 shadow-xl border-b-4 border-indigo-100 hover:border-indigo-300 transition-all">
         <h3 className="text-xl font-black text-indigo-900 mb-2 truncate">{level.title}</h3>
         <p className="text-slate-400 text-xs line-clamp-2 mb-4 italic">"{level.text}"</p>
         <div className="flex flex-wrap gap-2">
            {available.map(cat => (
              <button 
                key={cat} 
                onClick={() => startGame(level, cat)}
                className="px-3 py-1.5 bg-indigo-50 hover:bg-indigo-600 hover:text-white text-indigo-600 rounded-xl text-[10px] font-black uppercase transition-colors flex items-center"
              >
                <i className="fas fa-play mr-1.5 opacity-50"></i> {cat}s
              </button>
            ))}
         </div>
      </div>
    );
  };

  return (
    <div className={`min-h-screen w-full flex flex-col items-center justify-center p-4 bg-gradient-to-br from-blue-400 via-indigo-400 to-purple-500 overflow-hidden transition-all duration-1000 ${showKonamiEffect ? 'konami-active' : ''}`}>

      {lastUnlocked && (
        <div className="fixed top-8 right-8 z-[100] bg-white p-4 rounded-2xl shadow-2xl border-4 border-yellow-400 animate-in slide-in-from-right duration-500 flex items-center space-x-4">
          <div className="w-12 h-12 bg-yellow-400 rounded-xl flex items-center justify-center text-indigo-900 text-xl"><i className={`fas ${lastUnlocked.icon}`}></i></div>
          <div><span className="block text-[10px] font-black text-yellow-600 uppercase tracking-widest">¡Logro!</span><span className="block text-lg font-black text-indigo-900">{lastUnlocked.title}</span></div>
        </div>
      )}

      {view === GameView.MENU && (
        <div className="w-full max-w-6xl flex flex-col items-center animate-in fade-in zoom-in duration-500 overflow-y-auto max-h-screen py-12 px-4 scroll-smooth">
          <div className="text-center mb-12">
            <h1 className="text-8xl font-black text-white italic drop-shadow-[0_10px_10px_rgba(0,0,0,0.3)] tracking-tighter mb-2">GRAMMA<span className="text-yellow-300">CAT</span></h1>
            <p className="text-indigo-100 text-xl font-medium">Elige un texto y selecciona la categoría a buscar.</p>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 w-full mb-12">
            <div>
               <h2 className="text-3xl font-black text-white mb-6 uppercase tracking-tighter flex items-center">
                  <i className="fas fa-map-marked-alt mr-3 text-yellow-300"></i> Campaña Original
               </h2>
               <div className="grid grid-cols-1 gap-4">
                  {levels.map(lvl => <LevelCard key={lvl.id} level={lvl} />)}
               </div>
            </div>

            <div>
               <h2 className="text-3xl font-black text-white mb-6 uppercase tracking-tighter flex items-center">
                  <i className="fas fa-globe-americas mr-3 text-cyan-300"></i> Comunidad Online
               </h2>
               {isLoadingCommunity ? <div className="text-white text-center py-12"><i className="fas fa-spinner fa-spin text-4xl"></i></div> : (
                 <div className="grid grid-cols-1 gap-4">
                    {communityLevels.map(lvl => <LevelCard key={lvl.id} level={lvl} />)}
                    {communityLevels.length === 0 && <p className="text-white/50 text-center py-12 italic bg-black/10 rounded-3xl">No hay textos públicos aún. ¡Sé el primero!</p>}
                 </div>
               )}
            </div>
          </div>

          <button onClick={() => setView(GameView.ACHIEVEMENTS)} className="px-12 py-5 bg-white text-indigo-600 rounded-full text-2xl font-black shadow-2xl hover:scale-105 transition-all flex items-center mb-10 border-b-8 border-indigo-200">
            <i className="fas fa-trophy mr-3 text-yellow-400"></i> VER MIS LOGROS
          </button>
        </div>
      )}

      {view === GameView.ACHIEVEMENTS && <AchievementsModal achievements={achievements} onClose={() => setView(GameView.MENU)} />}

      {view === GameView.PLAYING && currentLevel && gameState.targetCategory && (
        <div className="w-full flex flex-col items-center animate-in slide-in-from-bottom duration-500">
          <GameHUD state={gameState} target={gameState.targetCategory} />
          <div className="w-full max-w-5xl bg-white/95 backdrop-blur-md rounded-[4rem] p-16 shadow-2xl border-b-8 border-indigo-200 min-h-[450px] flex flex-col justify-center relative">
            <div className="relative z-10 flex flex-wrap justify-center items-center gap-x-4 gap-y-6 text-5xl font-semibold text-slate-800">
              {currentLevel.words.map((w) => (
                <span key={w.id} onClick={() => handleWordClick(w)} className={`cursor-pointer px-5 py-2 rounded-3xl transition-all duration-300 transform hover:scale-110 active:scale-95 select-none
                    ${foundWords.includes(w.id) ? 'bg-green-500 text-white shadow-[0_6px_0_rgb(22,163,74)] -rotate-3 scale-110' : ''}
                    ${errorWords.includes(w.id) ? 'bg-rose-500 text-white shadow-lg rotate-3 scale-110 opacity-50' : ''}
                    ${!foundWords.includes(w.id) && !errorWords.includes(w.id) ? 'hover:bg-indigo-50 text-indigo-700' : ''}
                  `}>
                  {w.text}
                </span>
              ))}
            </div>
          </div>
        </div>
      )}

      {view === GameView.GAME_OVER && (
        <div className="text-center bg-white p-12 rounded-[3rem] shadow-2xl border-8 border-rose-500 animate-in zoom-in duration-300">
          <h2 className="text-7xl font-black text-slate-900 italic mb-8 tracking-tighter">¡TIEMPO AGOTADO!</h2>
          <button onClick={() => setView(GameView.MENU)} className="w-full py-6 bg-indigo-600 text-white rounded-3xl text-3xl font-black shadow-lg">CONTINUAR</button>
        </div>
      )}

      {view === GameView.EDITOR && (
        <Editor onClose={() => setView(GameView.MENU)} onSave={(newLevel) => {
          setLevels(prev => [newLevel, ...prev]);
          setView(GameView.MENU); // Ir al menú para elegir categoría
        }} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GameView, GameState, WordClass, Level, WordData, Achievement } from './types';
import { INITIAL_LEVELS, KONAMI_CODE, INITIAL_ACHIEVEMENTS } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';
import { AchievementsModal } from './components/AchievementsModal';
import { fetchCommunityLevels } from './services/supabaseService';

const App: React.FC = () => {
  const [view, setView] = useState<GameView>(GameView.MENU);
  const [gameState, setGameState] = useState<GameState>(() => {
    const savedStats = localStorage.getItem('grammaticat_stats');
    const stats = savedStats ? JSON.parse(savedStats) : { nounsFound: 0, levelsCompleted: 0 };
    return {
      score: 0,
      lives: 3,
      time: 0,
      levelIndex: 0,
      isPlaying: false,
      isGameOver: false,
      targetCategory: null,
      powerups: { hints: 2, shields: 1, cleaners: 1 },
      stats
    };
  });

  const [levels, setLevels] = useState<Level[]>(INITIAL_LEVELS);
  const [communityLevels, setCommunityLevels] = useState<Level[]>([]);
  const [isLoadingCommunity, setIsLoadingCommunity] = useState(false);
  const [currentLevel, setCurrentLevel] = useState<Level | null>(null);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [errorWords, setErrorWords] = useState<string[]>([]);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [showKonamiEffect, setShowKonamiEffect] = useState(false);
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('grammaticat_achievements');
    return saved ? JSON.parse(saved) : INITIAL_ACHIEVEMENTS;
  });

  const [lastUnlocked, setLastUnlocked] = useState<Achievement | null>(null);
  const timerRef = useRef<any>(null);

  useEffect(() => {
    const loadCommunity = async () => {
      setIsLoadingCommunity(true);
      const onlineLevels = await fetchCommunityLevels();
      setCommunityLevels(onlineLevels);
      setIsLoadingCommunity(false);
    };
    loadCommunity();
  }, []);

  const unlockAchievement = (id: string) => {
    setAchievements(prev => {
      const ach = prev.find(a => a.id === id);
      if (ach && !ach.unlocked) {
        const updated = prev.map(a => a.id === id ? { ...a, unlocked: true, unlockedAt: Date.now() } : a);
        setLastUnlocked({ ...ach, unlocked: true });
        setTimeout(() => setLastUnlocked(null), 4000);
        return updated;
      }
      return prev;
    });
  };

  const updateAchievementProgress = (id: string, increment: number) => {
    setAchievements(prev => {
      return prev.map(a => {
        if (a.id === id && !a.unlocked && a.goal) {
          const newProgress = (a.progress || 0) + increment;
          if (newProgress >= a.goal) {
            unlockAchievement(id);
            return { ...a, progress: a.goal, unlocked: true, unlockedAt: Date.now() };
          }
          return { ...a, progress: newProgress };
        }
        return a;
      });
    });
  };

  const startGame = (level: Level, category: WordClass) => {
    const words = level.words && level.words.length > 0 ? level.words : [];

    setCurrentLevel({ ...level, words });
    setGameState(prev => ({
      ...prev,
      time: level.timeLimit || 30,
      targetCategory: category,
      isPlaying: true,
      isGameOver: false
    }));
    setFoundWords([]);
    setErrorWords([]);
    setView(GameView.PLAYING);
  };

  const startRandomChallenge = (level: Level) => {
    const available = getAvailableCategories(level);
    // Preferir la categoría objetivo si existe, sino una aleatoria
    const category = level.targetCategory || available[Math.floor(Math.random() * available.length)];
    startGame(level, category);
  };

  const handleGameOver = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setView(GameView.GAME_OVER);
    setGameState(prev => ({ ...prev, isPlaying: false, isGameOver: true }));
  };

  useEffect(() => {
    if (gameState.isPlaying && gameState.time > 0) {
      timerRef.current = setInterval(() => {
        setGameState(prev => {
          if (prev.time <= 1) {
            handleGameOver();
            return { ...prev, time: 0 };
          }
          return { ...prev, time: prev.time - 1 };
        });
      }, 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [gameState.isPlaying]);

  const handleWordClick = (word: WordData) => {
    if (!gameState.isPlaying || !currentLevel || !gameState.targetCategory) return;
    if (foundWords.includes(word.id) || errorWords.includes(word.id)) return;

    if (word.category === gameState.targetCategory) {
      const newFound = [...foundWords, word.id];
      setFoundWords(newFound);

      if (word.category === WordClass.SUSTANTIVO) {
        setGameState(prev => ({ ...prev, stats: { ...prev.stats, nounsFound: prev.stats.nounsFound + 1 } }));
        updateAchievementProgress('noun_expert', 1);
      }

      setGameState(prev => ({ ...prev, score: prev.score + 10 }));

      const targetWordsCount = currentLevel.words.filter(w => w.category === gameState.targetCategory).length;
      if (newFound.length === targetWordsCount && targetWordsCount > 0) {
        unlockAchievement('first_steps');
        if (gameState.time > (currentLevel.timeLimit / 2)) unlockAchievement('speedster');

        setGameState(prev => ({ ...prev, isPlaying: false }));
        setTimeout(() => setView(GameView.MENU), 1500);
      }
    } else {
      setErrorWords(prev => [...prev, word.id]);
      setGameState(prev => {
        const newLives = prev.lives - 1;
        if (newLives <= 0) {
          handleGameOver();
          return { ...prev, lives: 0, time: 0 };
        }
        return { ...prev, lives: newLives, time: Math.max(0, prev.time - 5) };
      });
    }
  };

  const getAvailableCategories = (level: Level): WordClass[] => {
    const cats = new Set<WordClass>();
    level.words.forEach(w => cats.add(w.category));
    return Array.from(cats);
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const nextProgress = [...konamiProgress, e.key];
      const matchLength = nextProgress.length;
      const expected = KONAMI_CODE.slice(0, matchLength);
      if (JSON.stringify(nextProgress) === JSON.stringify(expected)) {
        if (matchLength === KONAMI_CODE.length) {
          unlockAchievement('hidden_discoverer');
          setShowKonamiEffect(true);
          setView(GameView.EDITOR);
          setKonamiProgress([]);
        } else { setKonamiProgress(nextProgress); }
      } else { setKonamiProgress([]); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress]);

  const LevelCard = ({ level }: { level: Level }) => {
    const available = getAvailableCategories(level);
    return (
      <div className="bg-white rounded-[2.5rem] p-8 shadow-xl border-b-8 border-indigo-100 hover:border-indigo-300 transition-all group">
         <div className="flex justify-between items-start mb-4">
            <h3 className="text-2xl font-black text-indigo-900 truncate">{level.title}</h3>
            <button 
              onClick={() => startRandomChallenge(level)}
              className="px-6 py-2 bg-rose-500 hover:bg-rose-400 text-white rounded-full text-xs font-black uppercase shadow-lg transform group-hover:scale-110 transition-all flex items-center"
            >
              <i className="fas fa-fire mr-2"></i> MODO RETO
            </button>
         </div>
         <p className="text-slate-400 text-sm line-clamp-2 mb-6 italic leading-relaxed">"{level.text}"</p>

         <div className="pt-4 border-t border-slate-100">
            <span className="text-[10px] font-black text-slate-300 uppercase tracking-widest block mb-3">Modo Práctica</span>
            <div className="flex flex-wrap gap-2">
               {available.map(cat => (
                 <button 
                   key={cat} 
                   onClick={() => startGame(level, cat)}
                   className="px-4 py-2 bg-indigo-50 hover:bg-indigo-600 hover:text-white text-indigo-600 rounded-2xl text-[10px] font-black uppercase transition-all shadow-sm flex items-center"
                 >
                   {cat}s
                 </button>
               ))}
            </div>
         </div>
      </div>
    );
  };

  return (
    <div className={`min-h-screen w-full flex flex-col items-center justify-center p-4 bg-gradient-to-br from-blue-400 via-indigo-400 to-purple-500 overflow-hidden transition-all duration-1000 ${showKonamiEffect ? 'konami-active' : ''}`}>

      {lastUnlocked && (
        <div className="fixed top-8 right-8 z-[100] bg-white p-4 rounded-2xl shadow-2xl border-4 border-yellow-400 animate-in slide-in-from-right duration-500 flex items-center space-x-4">
          <div className="w-12 h-12 bg-yellow-400 rounded-xl flex items-center justify-center text-indigo-900 text-xl"><i className={`fas ${lastUnlocked.icon}`}></i></div>
          <div><span className="block text-[10px] font-black text-yellow-600 uppercase tracking-widest">¡Logro!</span><span className="block text-lg font-black text-indigo-900">{lastUnlocked.title}</span></div>
        </div>
      )}

      {view === GameView.MENU && (
        <div className="w-full max-w-6xl flex flex-col items-center animate-in fade-in zoom-in duration-500 overflow-y-auto max-h-screen py-12 px-4 scroll-smooth custom-scrollbar">
          <div className="text-center mb-16">
            <h1 className="text-9xl font-black text-white italic drop-shadow-[0_15px_15px_rgba(0,0,0,0.3)] tracking-tighter mb-4 select-none">
              GRAMMA<span className="text-yellow-300">CAT</span>
            </h1>
            <div className="inline-block px-8 py-2 bg-white/20 backdrop-blur-md rounded-full border border-white/30">
              <p className="text-white text-xl font-bold italic tracking-wide">El desafío definitivo de las palabras</p>
            </div>
          </div>

          <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 w-full mb-16">
            <div className="space-y-8">
               <h2 className="text-4xl font-black text-white uppercase tracking-tighter flex items-center drop-shadow-md">
                  <i className="fas fa-medal mr-4 text-yellow-300"></i> Campaña
               </h2>
               <div className="grid grid-cols-1 gap-6">
                  {levels.map(lvl => <LevelCard key={lvl.id} level={lvl} />)}
               </div>
            </div>

            <div className="space-y-8">
               <h2 className="text-4xl font-black text-white uppercase tracking-tighter flex items-center drop-shadow-md">
                  <i className="fas fa-cloud mr-4 text-cyan-300"></i> Comunidad
               </h2>
               {isLoadingCommunity ? (
                 <div className="bg-white/10 rounded-[2.5rem] p-12 flex flex-col items-center border-2 border-dashed border-white/20">
                   <i className="fas fa-spinner fa-spin text-6xl text-white/50 mb-4"></i>
                   <span className="text-white font-bold animate-pulse">Buscando retos online...</span>
                 </div>
               ) : (
                 <div className="grid grid-cols-1 gap-6">
                    {communityLevels.map(lvl => <LevelCard key={lvl.id} level={lvl} />)}
                    {communityLevels.length === 0 && (
                      <div className="bg-black/10 rounded-[2.5rem] p-16 text-center border-2 border-dashed border-white/10">
                        <i className="fas fa-ghost text-4xl text-white/20 mb-4 block"></i>
                        <p className="text-white/40 font-bold italic">No hay textos públicos aún.</p>
                      </div>
                    )}
                 </div>
               )}
            </div>
          </div>

          <div className="flex flex-wrap justify-center gap-6 mb-16">
            <button onClick={() => setView(GameView.ACHIEVEMENTS)} className="px-12 py-5 bg-white text-indigo-600 rounded-full text-2xl font-black shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center border-b-8 border-indigo-200">
              <i className="fas fa-trophy mr-4 text-yellow-400"></i> MIS LOGROS
            </button>
            <button 
              onClick={() => {
                const all = [...levels, ...communityLevels];
                if (all.length > 0) startRandomChallenge(all[Math.floor(Math.random() * all.length)]);
              }}
              className="px-12 py-5 bg-yellow-400 text-indigo-900 rounded-full text-2xl font-black shadow-2xl hover:scale-105 active:scale-95 transition-all flex items-center border-b-8 border-yellow-600"
            >
              <i className="fas fa-random mr-4"></i> RETO ALEATORIO
            </button>
          </div>
        </div>
      )}

      {view === GameView.ACHIEVEMENTS && <AchievementsModal achievements={achievements} onClose={() => setView(GameView.MENU)} />}

      {view === GameView.PLAYING && currentLevel && gameState.targetCategory && (
        <div className="w-full h-full flex flex-col items-center justify-center animate-in slide-in-from-bottom duration-700">
          <GameHUD state={gameState} target={gameState.targetCategory} />
          <div className="w-full max-w-5xl bg-white/95 backdrop-blur-md rounded-[5rem] p-20 shadow-2xl border-b-8 border-indigo-200 min-h-[500px] flex flex-col justify-center relative overflow-hidden">
            {/* Elementos decorativos de fondo */}
            <div className="absolute top-0 right-0 p-8 opacity-5">
              <i className="fas fa-cat text-[20rem] -rotate-12"></i>
            </div>

            <div className="relative z-10 flex flex-wrap justify-center items-center gap-x-6 gap-y-8 text-5xl font-black text-slate-800">
              {currentLevel.words.map((w) => (
                <span 
                  key={w.id} 
                  onClick={() => handleWordClick(w)} 
                  className={`cursor-pointer px-7 py-3 rounded-[2rem] transition-all duration-300 transform select-none relative
                    ${foundWords.includes(w.id) ? 'bg-green-500 text-white shadow-[0_8px_0_rgb(22,163,74)] -rotate-3 scale-110 translate-y-[-4px]' : ''}
                    ${errorWords.includes(w.id) ? 'bg-rose-500 text-white shadow-lg rotate-3 scale-110 opacity-40 translate-y-[4px]' : ''}
                    ${!foundWords.includes(w.id) && !errorWords.includes(w.id) ? 'hover:bg-indigo-50 hover:text-indigo-600 hover:scale-110 active:scale-95' : 'pointer-events-none'}
                  `}
                >
                  {w.text}
                  {foundWords.includes(w.id) && (
                    <i className="fas fa-check-circle absolute -top-2 -right-2 text-xl text-yellow-300 animate-bounce"></i>
                  )}
                </span>
              ))}
            </div>

            {/* Mensaje de éxito al ganar */}
            {!gameState.isPlaying && !gameState.isGameOver && (
              <div className="absolute inset-0 bg-green-500/20 backdrop-blur-sm flex items-center justify-center z-20 animate-in fade-in duration-500">
                <div className="bg-white p-12 rounded-[3rem] shadow-2xl border-8 border-green-500 text-center scale-110">
                  <i className="fas fa-star text-6xl text-yellow-400 mb-4 animate-spin-slow"></i>
                  <h2 className="text-5xl font-black text-slate-900 mb-2 uppercase italic tracking-tighter">¡NIVEL COMPLETADO!</h2>
                  <p className="text-xl font-bold text-green-600">Siguiente reto en camino...</p>
                </div>
              </div>
            )}
          </div>
        </div>
      )}

      {view === GameView.GAME_OVER && (
        <div className="text-center bg-white p-16 rounded-[4rem] shadow-2xl border-b-8 border-rose-600 border-x-8 border-rose-500 animate-in zoom-in duration-300">
          <i className="fas fa-skull-crossbones text-7xl text-rose-500 mb-6 block"></i>
          <h2 className="text-8xl font-black text-slate-900 italic mb-4 tracking-tighter uppercase">¡OOPS!</h2>
          <p className="text-2xl font-bold text-slate-400 mb-10">Se acabó el tiempo o las vidas...</p>
          <button 
            onClick={() => setView(GameView.MENU)} 
            className="w-full py-8 bg-indigo-600 hover:bg-indigo-500 text-white rounded-[2rem] text-4xl font-black shadow-xl transform active:scale-95 transition-all"
          >
            VOLVER AL MENÚ
          </button>
        </div>
      )}

      {view === GameView.EDITOR && (
        <Editor onClose={() => setView(GameView.MENU)} onSave={(newLevel) => {
          setLevels(prev => [newLevel, ...prev]);
          setView(GameView.MENU);
        }} />
      )}
    </div>
  );
};

export default App;

export enum WordClass {
  SUSTANTIVO = 'Sustantivo',
  ADJETIVO = 'Adjetivo',
  VERBO = 'Verbo',
  ADVERBIO = 'Adverbio',
  PRONOMBRE = 'Pronombre',
  PREPOSICION = 'Preposición',
  CONJUNCION = 'Conjunción',
  DETERMINANTE = 'Determinante'
}

export interface WordData {
  text: string;
  category: WordClass;
  id: string;
}

export interface Level {
  id: number;
  title: string;
  text: string;
  words: WordData[];
  timeLimit: number;
  targetCategory?: WordClass;
}

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: string;
  unlocked: boolean;
  unlockedAt?: number;
  progress?: number;
  goal?: number;
}

export interface GameState {
  score: number;
  lives: number;
  time: number;
  levelIndex: number;
  isPlaying: boolean;
  isGameOver: boolean;
  targetCategory: WordClass | null;
  mode: 'PRACTICE' | 'CHALLENGE' | null;
  powerups: {
    hints: number;
    shields: number;
    cleaners: number;
  };
  stats: {
    nounsFound: number;
    levelsCompleted: number;
  };
}

export enum GameView {
  MENU = 'MENU',
  LEVEL_SELECT = 'LEVEL_SELECT',
  PLAYING = 'PLAYING',
  EDITOR = 'EDITOR',
  GAME_OVER = 'GAME_OVER',
  ACHIEVEMENTS = 'ACHIEVEMENTS'
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GameView, GameState, WordClass, Level, WordData, Achievement } from './types';
import { INITIAL_LEVELS, KONAMI_CODE, INITIAL_ACHIEVEMENTS } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';
import { AchievementsModal } from './components/AchievementsModal';
import { fetchCommunityLevels } from './services/supabaseService';

const App: React.FC = () => {
  const [view, setView] = useState<GameView>(GameView.MENU);
  const [gameState, setGameState] = useState<GameState>(() => {
    const savedStats = localStorage.getItem('grammaticat_stats');
    const stats = savedStats ? JSON.parse(savedStats) : { nounsFound: 0, levelsCompleted: 0 };
    return {
      score: 0,
      lives: 3,
      time: 0,
      levelIndex: 0,
      isPlaying: false,
      isGameOver: false,
      targetCategory: null,
      mode: null,
      powerups: { hints: 2, shields: 1, cleaners: 1 },
      stats
    };
  });

  const [levels, setLevels] = useState<Level[]>(INITIAL_LEVELS);
  const [communityLevels, setCommunityLevels] = useState<Level[]>([]);
  const [isLoadingCommunity, setIsLoadingCommunity] = useState(false);
  const [currentLevel, setCurrentLevel] = useState<Level | null>(null);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [errorWords, setErrorWords] = useState<string[]>([]);
  const [highlightedWords, setHighlightedWords] = useState<string[]>([]);
  const [cleanedWords, setCleanedWords] = useState<string[]>([]);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [showKonamiEffect, setShowKonamiEffect] = useState(false);
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('grammaticat_achievements');
    return saved ? JSON.parse(saved) : INITIAL_ACHIEVEMENTS;
  });

  const [lastUnlocked, setLastUnlocked] = useState<Achievement | null>(null);
  const timerRef = useRef<any>(null);

  // Cargar niveles de la comunidad para Práctica
  useEffect(() => {
    if (view === GameView.LEVEL_SELECT) {
      const loadCommunity = async () => {
        setIsLoadingCommunity(true);
        const onlineLevels = await fetchCommunityLevels();
        setCommunityLevels(onlineLevels);
        setIsLoadingCommunity(false);
      };
      loadCommunity();
    }
  }, [view]);

  const unlockAchievement = (id: string) => {
    setAchievements(prev => {
      const ach = prev.find(a => a.id === id);
      if (ach && !ach.unlocked) {
        const updated = prev.map(a => a.id === id ? { ...a, unlocked: true, unlockedAt: Date.now() } : a);
        setLastUnlocked({ ...ach, unlocked: true });
        setTimeout(() => setLastUnlocked(null), 4000);
        return updated;
      }
      return prev;
    });
  };

  const startGame = (level: Level, category: WordClass, mode: 'PRACTICE' | 'CHALLENGE') => {
    setCurrentLevel(level);
    setGameState(prev => ({
      ...prev,
      time: level.timeLimit || 30,
      targetCategory: category,
      mode,
      isPlaying: true,
      isGameOver: false
    }));
    setFoundWords([]);
    setErrorWords([]);
    setHighlightedWords([]);
    setCleanedWords([]);
    setView(GameView.PLAYING);
  };

  const startRandomChallenge = async () => {
    // Si no han cargado aún, intentamos usar los iniciales
    const allAvailable = [...levels, ...communityLevels];
    const randomLevel = allAvailable[Math.floor(Math.random() * allAvailable.length)];

    // Obtener categorías reales del texto
    const categories = Array.from(new Set(randomLevel.words.map(w => w.category)));
    const randomCategory = categories[Math.floor(Math.random() * categories.length)] as WordClass;

    startGame(randomLevel, randomCategory, 'CHALLENGE');
  };

  const usePowerup = (type: 'hint' | 'clean' | 'shield') => {
    if (!gameState.isPlaying || !currentLevel || !gameState.targetCategory) return;

    if (type === 'hint' && gameState.powerups.hints > 0) {
      const remainingTargetWords = currentLevel.words.filter(
        w => w.category === gameState.targetCategory && !foundWords.includes(w.id) && !highlightedWords.includes(w.id)
      );
      if (remainingTargetWords.length > 0) {
        const randomWord = remainingTargetWords[Math.floor(Math.random() * remainingTargetWords.length)];
        setHighlightedWords(prev => [...prev, randomWord.id]);
        setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, hints: prev.powerups.hints - 1 } }));
      }
    } else if (type === 'clean' && gameState.powerups.cleaners > 0) {
      const incorrectWords = currentLevel.words.filter(
        w => w.category !== gameState.targetCategory && !cleanedWords.includes(w.id)
      );
      if (incorrectWords.length > 0) {
        // Limpiar hasta 3 palabras incorrectas
        const toClean = incorrectWords.sort(() => 0.5 - Math.random()).slice(0, 3).map(w => w.id);
        setCleanedWords(prev => [...prev, ...toClean]);
        setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, cleaners: prev.powerups.cleaners - 1 } }));
      }
    } else if (type === 'shield' && gameState.powerups.shields > 0) {
      // El escudo se consume automáticamente en handleWordClick si es > 0 y fallas
      // Aquí simplemente podríamos indicar que está activo si quisiéramos una animación previa
    }
  };

  const handleGameOver = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setView(GameView.GAME_OVER);
    setGameState(prev => ({ ...prev, isPlaying: false, isGameOver: true }));
  };

  useEffect(() => {
    if (gameState.isPlaying && gameState.time > 0) {
      timerRef.current = setInterval(() => {
        setGameState(prev => {
          if (prev.time <= 1) {
            handleGameOver();
            return { ...prev, time: 0 };
          }
          return { ...prev, time: prev.time - 1 };
        });
      }, 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [gameState.isPlaying]);

  const handleWordClick = (word: WordData) => {
    if (!gameState.isPlaying || !currentLevel || !gameState.targetCategory) return;
    if (foundWords.includes(word.id) || errorWords.includes(word.id) || cleanedWords.includes(word.id)) return;

    if (word.category === gameState.targetCategory) {
      const newFound = [...foundWords, word.id];
      setFoundWords(newFound);
      setGameState(prev => ({ ...prev, score: prev.score + 10 }));

      const targetWordsCount = currentLevel.words.filter(w => w.category === gameState.targetCategory).length;
      if (newFound.length === targetWordsCount) {
        // Victoria del nivel
        setGameState(prev => {
          // Recompensa aleatoria
          const rewardRoll = Math.random();
          const newPowerups = { ...prev.powerups };
          let bonusMsg = "";

          if (rewardRoll < 0.3) {
            newPowerups.hints += 1;
            bonusMsg = "+1 Pista";
          } else if (rewardRoll < 0.6) {
            newPowerups.cleaners += 1;
            bonusMsg = "+1 Limpiar";
          } else {
            newPowerups.shields += 1;
            bonusMsg = "+1 Escudo";
          }

          return { 
            ...prev, 
            isPlaying: false, 
            lives: Math.min(5, prev.lives + (Math.random() > 0.8 ? 1 : 0)), // Probabilidad de vida extra
            powerups: newPowerups,
            stats: { ...prev.stats, levelsCompleted: prev.stats.levelsCompleted + 1 }
          };
        });

        unlockAchievement('first_steps');
        setTimeout(() => {
          if (gameState.mode === 'CHALLENGE') {
            startRandomChallenge(); // Encadenar en modo reto
          } else {
            setView(GameView.LEVEL_SELECT);
          }
        }, 2000);
      }
    } else {
      // Error
      if (gameState.powerups.shields > 0) {
        // Usar escudo
        setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, shields: prev.powerups.shields - 1 } }));
        setErrorWords(prev => [...prev, word.id]); // Visualmente se marca pero no quita vida ni tiempo extra
      } else {
        setErrorWords(prev => [...prev, word.id]);
        setGameState(prev => {
          const newLives = prev.lives - 1;
          if (newLives <= 0) {
            handleGameOver();
            return { ...prev, lives: 0, time: 0 };
          }
          return { ...prev, lives: newLives, time: Math.max(0, prev.time - 5) };
        });
      }
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const nextProgress = [...konamiProgress, e.key];
      const matchLength = nextProgress.length;
      const expected = KONAMI_CODE.slice(0, matchLength);
      if (JSON.stringify(nextProgress) === JSON.stringify(expected)) {
        if (matchLength === KONAMI_CODE.length) {
          unlockAchievement('hidden_discoverer');
          setShowKonamiEffect(true);
          setView(GameView.EDITOR);
          setKonamiProgress([]);
        } else { setKonamiProgress(nextProgress); }
      } else { setKonamiProgress([]); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress]);

  const LevelCard = ({ level }: { level: Level }) => {
    const cats = Array.from(new Set(level.words.map(w => w.category)));
    return (
      <div className="bg-white rounded-3xl p-6 shadow-xl border-b-4 border-indigo-100 hover:shadow-2xl transition-all">
         <h3 className="text-xl font-black text-indigo-900 mb-2">{level.title}</h3>
         <p className="text-slate-400 text-xs line-clamp-2 mb-4 italic">"{level.text}"</p>
         <div className="flex flex-wrap gap-2">
            {cats.map(cat => (
              <button 
                key={cat} 
                onClick={() => startGame(level, cat as WordClass, 'PRACTICE')}
                className="px-3 py-1.5 bg-indigo-50 hover:bg-indigo-600 hover:text-white text-indigo-600 rounded-xl text-[10px] font-black uppercase transition-all"
              >
                {cat}s
              </button>
            ))}
         </div>
      </div>
    );
  };

  return (
    <div className={`min-h-screen w-full flex flex-col items-center justify-center p-4 bg-gradient-to-br from-blue-400 via-indigo-400 to-purple-500 overflow-hidden transition-all duration-1000 ${showKonamiEffect ? 'konami-active' : ''}`}>

      {/* HUD de Logros */}
      {lastUnlocked && (
        <div className="fixed top-8 right-8 z-[100] bg-white p-4 rounded-2xl shadow-2xl border-4 border-yellow-400 animate-in slide-in-from-right duration-500 flex items-center space-x-4">
          <div className="w-12 h-12 bg-yellow-400 rounded-xl flex items-center justify-center text-indigo-900 text-xl"><i className={`fas ${lastUnlocked.icon}`}></i></div>
          <div><span className="block text-[10px] font-black text-yellow-600 uppercase tracking-widest">¡Logro!</span><span className="block text-lg font-black text-indigo-900">{lastUnlocked.title}</span></div>
        </div>
      )}

      {/* VISTA: MENÚ PRINCIPAL (Selección de Modo) */}
      {view === GameView.MENU && (
        <div className="flex flex-col items-center animate-in fade-in zoom-in duration-700">
          <h1 className="text-9xl font-black text-white italic drop-shadow-[0_15px_15px_rgba(0,0,0,0.3)] tracking-tighter mb-16 select-none">
            GRAMMA<span className="text-yellow-300">CAT</span>
          </h1>

          <div className="flex flex-col md:flex-row gap-10">
            <button 
              onClick={() => setView(GameView.LEVEL_SELECT)}
              className="group relative w-72 h-72 bg-white rounded-[3rem] shadow-2xl border-b-8 border-indigo-200 hover:scale-105 active:scale-95 transition-all flex flex-col items-center justify-center overflow-hidden"
            >
              <div className="absolute inset-0 bg-indigo-600 opacity-0 group-hover:opacity-10 transition-opacity"></div>
              <i className="fas fa-graduation-cap text-7xl text-indigo-500 mb-4 group-hover:rotate-12 transition-transform"></i>
              <span className="text-3xl font-black text-indigo-900 uppercase italic tracking-tighter">PRÁCTICA</span>
              <p className="text-xs font-bold text-slate-400 mt-2">Elige tu propio reto</p>
            </button>

            <button 
              onClick={startRandomChallenge}
              className="group relative w-72 h-72 bg-yellow-400 rounded-[3rem] shadow-2xl border-b-8 border-yellow-600 hover:scale-105 active:scale-95 transition-all flex flex-col items-center justify-center overflow-hidden"
            >
              <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-20 transition-opacity"></div>
              <i className="fas fa-fire text-7xl text-indigo-900 mb-4 group-hover:scale-125 transition-transform animate-pulse"></i>
              <span className="text-3xl font-black text-indigo-900 uppercase italic tracking-tighter">RETO</span>
              <p className="text-xs font-bold text-indigo-800/60 mt-2">Nivel y Clase aleatoria</p>
            </button>
          </div>

          <div className="mt-16 flex gap-4">
            <button onClick={() => setView(GameView.ACHIEVEMENTS)} className="px-8 py-3 bg-white/20 hover:bg-white/40 text-white rounded-2xl font-black border-2 border-white/30 transition-all flex items-center">
              <i className="fas fa-trophy mr-3"></i> LOGROS
            </button>
          </div>
        </div>
      )}

      {/* VISTA: SELECCIÓN DE NIVEL (Solo para Práctica) */}
      {view === GameView.LEVEL_SELECT && (
        <div className="w-full max-w-6xl flex flex-col items-center animate-in slide-in-from-right duration-500 overflow-y-auto max-h-[90vh] custom-scrollbar p-6">
          <div className="w-full flex justify-between items-center mb-10">
            <button onClick={() => setView(GameView.MENU)} className="p-4 bg-white/20 text-white rounded-full hover:bg-white/40 transition-all"><i className="fas fa-arrow-left text-2xl"></i></button>
            <h2 className="text-5xl font-black text-white uppercase italic tracking-tighter">BIBLIOTECA DE TEXTOS</h2>
            <div className="w-12"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full">
            <div className="space-y-6">
               <h3 className="text-2xl font-black text-yellow-300 uppercase tracking-tighter flex items-center drop-shadow-md">
                 <i className="fas fa-book-open mr-3"></i> Textos Base
               </h3>
               {levels.map(lvl => <LevelCard key={lvl.id} level={lvl} />)}
            </div>
            <div className="space-y-6">
               <h3 className="text-2xl font-black text-cyan-300 uppercase tracking-tighter flex items-center drop-shadow-md">
                 <i className="fas fa-cloud mr-3"></i> Comunidad
               </h3>
               {isLoadingCommunity ? <div className="text-white text-center py-10 animate-pulse"><i className="fas fa-spinner fa-spin text-4xl mb-2 block"></i> Cargando...</div> : (
                 communityLevels.length > 0 ? communityLevels.map(lvl => <LevelCard key={lvl.id} level={lvl} />) : 
                 <p className="text-white/40 italic text-center py-10 bg-black/10 rounded-3xl border-2 border-dashed border-white/10">No hay textos online disponibles aún.</p>
               )}
            </div>
          </div>
        </div>
      )}

      {/* VISTA: JUEGO (Playing) */}
      {view === GameView.PLAYING && currentLevel && gameState.targetCategory && (
        <div className="w-full flex flex-col items-center justify-center animate-in zoom-in duration-500">
          <GameHUD state={gameState} target={gameState.targetCategory} />

          <div className="w-full max-w-5xl bg-white rounded-[5rem] p-20 shadow-2xl border-b-8 border-indigo-200 min-h-[450px] flex flex-col justify-center relative">
            <div className="relative z-10 flex flex-wrap justify-center items-center gap-x-6 gap-y-8 text-5xl font-black text-slate-800 leading-normal">
              {currentLevel.words.map((w) => (
                <span 
                  key={w.id} 
                  onClick={() => handleWordClick(w)} 
                  className={`cursor-pointer px-6 py-2 rounded-[2rem] transition-all duration-300 transform select-none
                    ${foundWords.includes(w.id) ? 'bg-green-500 text-white shadow-[0_8px_0_rgb(22,163,74)] -rotate-3 scale-110 pointer-events-none' : ''}
                    ${errorWords.includes(w.id) ? 'bg-rose-500 text-white shadow-lg rotate-3 scale-110 opacity-40 pointer-events-none' : ''}
                    ${cleanedWords.includes(w.id) ? 'opacity-20 grayscale pointer-events-none scale-90' : ''}
                    ${highlightedWords.includes(w.id) && !foundWords.includes(w.id) ? 'ring-8 ring-yellow-400 animate-pulse shadow-yellow-200' : ''}
                    ${!foundWords.includes(w.id) && !errorWords.includes(w.id) && !cleanedWords.includes(w.id) ? 'hover:bg-indigo-50 hover:text-indigo-600' : ''}
                  `}
                >
                  {w.text}
                </span>
              ))}
            </div>

            {/* Mensaje de éxito */}
            {!gameState.isPlaying && !gameState.isGameOver && (
              <div className="absolute inset-0 bg-green-500/20 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-300 rounded-[5rem]">
                <div className="bg-white p-12 rounded-[3rem] shadow-2xl border-8 border-green-500 text-center scale-110">
                   <h2 className="text-6xl font-black text-indigo-900 mb-2 italic tracking-tighter">¡TEXTO SUPERADO!</h2>
                   <div className="flex justify-center gap-4 text-3xl mb-4">
                      <i className="fas fa-star text-yellow-400 animate-bounce"></i>
                      <i className="fas fa-star text-yellow-400 animate-bounce [animation-delay:200ms]"></i>
                      <i className="fas fa-star text-yellow-400 animate-bounce [animation-delay:400ms]"></i>
                   </div>
                   <p className="text-xl font-bold text-green-600 uppercase tracking-widest">Recompensa obtenida</p>
                </div>
              </div>
            )}
          </div>

          {/* HUD de Ayudas (Mockup inferior) */}
          <div className="mt-12 flex gap-8">
            <button 
              onClick={() => usePowerup('hint')}
              disabled={gameState.powerups.hints <= 0}
              className={`w-32 h-32 flex flex-col items-center justify-center rounded-[2rem] shadow-xl border-b-8 transition-all active:scale-95
                ${gameState.powerups.hints > 0 ? 'bg-cyan-300 border-cyan-500 hover:bg-cyan-200' : 'bg-slate-200 border-slate-300 opacity-50'}
              `}
            >
              <i className="fas fa-lightbulb text-4xl text-cyan-800 mb-1"></i>
              <span className="text-xs font-black text-cyan-900 uppercase">PISTA ({gameState.powerups.hints})</span>
            </button>

            <button 
              onClick={() => usePowerup('clean')}
              disabled={gameState.powerups.cleaners <= 0}
              className={`w-32 h-32 flex flex-col items-center justify-center rounded-[2rem] shadow-xl border-b-8 transition-all active:scale-95
                ${gameState.powerups.cleaners > 0 ? 'bg-rose-300 border-rose-500 hover:bg-rose-200' : 'bg-slate-200 border-slate-300 opacity-50'}
              `}
            >
              <i className="fas fa-broom text-4xl text-rose-800 mb-1"></i>
              <span className="text-xs font-black text-rose-900 uppercase">LIMPIAR ({gameState.powerups.cleaners})</span>
            </button>

            <button 
              onClick={() => usePowerup('shield')}
              disabled={gameState.powerups.shields <= 0}
              className={`w-32 h-32 flex flex-col items-center justify-center rounded-[2rem] shadow-xl border-b-8 transition-all active:scale-95
                ${gameState.powerups.shields > 0 ? 'bg-lime-300 border-lime-500 hover:bg-lime-200 ring-4 ring-lime-400/50' : 'bg-slate-200 border-slate-300 opacity-50'}
              `}
            >
              <i className="fas fa-shield-alt text-4xl text-lime-800 mb-1"></i>
              <span className="text-xs font-black text-lime-900 uppercase">ESCUDO ({gameState.powerups.shields})</span>
            </button>
          </div>
        </div>
      )}

      {/* Pantalla Game Over */}
      {view === GameView.GAME_OVER && (
        <div className="text-center bg-white p-16 rounded-[4rem] shadow-2xl border-x-8 border-b-8 border-rose-500 animate-in zoom-in duration-300">
          <i className="fas fa-skull text-8xl text-rose-500 mb-6 block"></i>
          <h2 className="text-7xl font-black text-slate-900 italic tracking-tighter mb-4">GAME OVER</h2>
          <p className="text-2xl font-bold text-slate-400 mb-10 italic">¡No te rindas, vuelve a intentarlo!</p>
          <button onClick={() => setView(GameView.MENU)} className="w-full py-6 bg-indigo-600 hover:bg-indigo-500 text-white rounded-3xl text-3xl font-black shadow-lg transition-all">MENÚ PRINCIPAL</button>
        </div>
      )}

      {/* Editor & Achievements */}
      {view === GameView.ACHIEVEMENTS && <AchievementsModal achievements={achievements} onClose={() => setView(GameView.MENU)} />}
      {view === GameView.EDITOR && (
        <Editor onClose={() => setView(GameView.MENU)} onSave={(newLevel) => {
          setLevels(prev => [newLevel, ...prev]);
          setView(GameView.MENU);
        }} />
      )}
    </div>
  );
};

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { GameView, GameState, WordClass, Level, WordData, Achievement } from './types';
import { INITIAL_LEVELS, KONAMI_CODE, INITIAL_ACHIEVEMENTS } from './constants';
import { GameHUD } from './components/GameHUD';
import { Editor } from './components/Editor';
import { AchievementsModal } from './components/AchievementsModal';
import { fetchCommunityLevels } from './services/supabaseService';

// Helper para pluralizar correctamente en español
export const getPluralCategory = (cat: WordClass): string => {
  switch (cat) {
    case WordClass.PREPOSICION: return 'Preposiciones';
    case WordClass.CONJUNCION: return 'Conjunciones';
    default: return `${cat}s`;
  }
};

const App: React.FC = () => {
  const [view, setView] = useState<GameView>(GameView.MENU);
  const [gameState, setGameState] = useState<GameState>(() => {
    const savedStats = localStorage.getItem('grammaticat_stats');
    const stats = savedStats ? JSON.parse(savedStats) : { nounsFound: 0, levelsCompleted: 0 };
    return {
      score: 0,
      lives: 3,
      time: 0,
      levelIndex: 0,
      isPlaying: false,
      isGameOver: false,
      targetCategory: null,
      mode: null,
      powerups: { hints: 2, shields: 1, cleaners: 1 },
      stats
    };
  });

  const [levels, setLevels] = useState<Level[]>(INITIAL_LEVELS);
  const [communityLevels, setCommunityLevels] = useState<Level[]>([]);
  const [isLoadingCommunity, setIsLoadingCommunity] = useState(false);
  const [currentLevel, setCurrentLevel] = useState<Level | null>(null);
  const [foundWords, setFoundWords] = useState<string[]>([]);
  const [errorWords, setErrorWords] = useState<string[]>([]);
  const [highlightedWords, setHighlightedWords] = useState<string[]>([]);
  const [cleanedWords, setCleanedWords] = useState<string[]>([]);
  const [konamiProgress, setKonamiProgress] = useState<string[]>([]);
  const [showKonamiEffect, setShowKonamiEffect] = useState(false);
  const [achievements, setAchievements] = useState<Achievement[]>(() => {
    const saved = localStorage.getItem('grammaticat_achievements');
    return saved ? JSON.parse(saved) : INITIAL_ACHIEVEMENTS;
  });

  const [lastUnlocked, setLastUnlocked] = useState<Achievement | null>(null);
  const timerRef = useRef<any>(null);

  useEffect(() => {
    if (view === GameView.LEVEL_SELECT || view === GameView.MENU) {
      const loadCommunity = async () => {
        setIsLoadingCommunity(true);
        const onlineLevels = await fetchCommunityLevels();
        setCommunityLevels(onlineLevels);
        setIsLoadingCommunity(false);
      };
      loadCommunity();
    }
  }, [view]);

  const unlockAchievement = (id: string) => {
    setAchievements(prev => {
      const ach = prev.find(a => a.id === id);
      if (ach && !ach.unlocked) {
        const updated = prev.map(a => a.id === id ? { ...a, unlocked: true, unlockedAt: Date.now() } : a);
        setLastUnlocked({ ...ach, unlocked: true });
        setTimeout(() => setLastUnlocked(null), 4000);
        return updated;
      }
      return prev;
    });
  };

  const startGame = (level: Level, category: WordClass, mode: 'PRACTICE' | 'CHALLENGE') => {
    setCurrentLevel(level);
    setGameState(prev => ({
      ...prev,
      time: level.timeLimit || 30,
      targetCategory: category,
      mode,
      isPlaying: true,
      isGameOver: false
    }));
    setFoundWords([]);
    setErrorWords([]);
    setHighlightedWords([]);
    setCleanedWords([]);
    setView(GameView.PLAYING);
  };

  const startRandomChallenge = async () => {
    const allAvailable = [...levels, ...communityLevels];
    if (allAvailable.length === 0) return;

    const randomLevel = allAvailable[Math.floor(Math.random() * allAvailable.length)];
    const categories = Array.from(new Set(randomLevel.words.map(w => w.category)));
    const randomCategory = categories[Math.floor(Math.random() * categories.length)] as WordClass;

    startGame(randomLevel, randomCategory, 'CHALLENGE');
  };

  const usePowerup = (type: 'hint' | 'clean' | 'shield') => {
    if (!gameState.isPlaying || !currentLevel || !gameState.targetCategory) return;

    if (type === 'hint' && gameState.powerups.hints > 0) {
      const remainingTargetWords = currentLevel.words.filter(
        w => w.category === gameState.targetCategory && !foundWords.includes(w.id) && !highlightedWords.includes(w.id)
      );
      if (remainingTargetWords.length > 0) {
        const randomWord = remainingTargetWords[Math.floor(Math.random() * remainingTargetWords.length)];
        setHighlightedWords(prev => [...prev, randomWord.id]);
        setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, hints: prev.powerups.hints - 1 } }));
      }
    } else if (type === 'clean' && gameState.powerups.cleaners > 0) {
      const incorrectWords = currentLevel.words.filter(
        w => w.category !== gameState.targetCategory && !cleanedWords.includes(w.id)
      );
      if (incorrectWords.length > 0) {
        const toClean = incorrectWords.sort(() => 0.5 - Math.random()).slice(0, 3).map(w => w.id);
        setCleanedWords(prev => [...prev, ...toClean]);
        setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, cleaners: prev.powerups.cleaners - 1 } }));
      }
    }
  };

  const handleGameOver = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    setView(GameView.GAME_OVER);
    setGameState(prev => ({ ...prev, isPlaying: false, isGameOver: true }));
  };

  useEffect(() => {
    if (gameState.isPlaying && gameState.time > 0) {
      timerRef.current = setInterval(() => {
        setGameState(prev => {
          if (prev.time <= 1) {
            handleGameOver();
            return { ...prev, time: 0 };
          }
          return { ...prev, time: prev.time - 1 };
        });
      }, 1000);
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [gameState.isPlaying]);

  const handleWordClick = (word: WordData) => {
    if (!gameState.isPlaying || !currentLevel || !gameState.targetCategory) return;
    if (foundWords.includes(word.id) || errorWords.includes(word.id) || cleanedWords.includes(word.id)) return;

    if (word.category === gameState.targetCategory) {
      const newFound = [...foundWords, word.id];
      setFoundWords(newFound);
      setGameState(prev => ({ ...prev, score: prev.score + 10 }));

      const targetWordsCount = currentLevel.words.filter(w => w.category === gameState.targetCategory).length;
      if (newFound.length === targetWordsCount) {
        setGameState(prev => {
          const rewardRoll = Math.random();
          const newPowerups = { ...prev.powerups };
          if (rewardRoll < 0.3) newPowerups.hints += 1;
          else if (rewardRoll < 0.6) newPowerups.cleaners += 1;
          else newPowerups.shields += 1;

          return { 
            ...prev, 
            isPlaying: false, 
            lives: Math.min(5, prev.lives + (Math.random() > 0.8 ? 1 : 0)),
            powerups: newPowerups,
            stats: { ...prev.stats, levelsCompleted: prev.stats.levelsCompleted + 1 }
          };
        });

        unlockAchievement('first_steps');
        setTimeout(() => {
          if (gameState.mode === 'CHALLENGE') {
            startRandomChallenge();
          } else {
            setView(GameView.LEVEL_SELECT);
          }
        }, 2000);
      }
    } else {
      if (gameState.powerups.shields > 0) {
        setGameState(prev => ({ ...prev, powerups: { ...prev.powerups, shields: prev.powerups.shields - 1 } }));
        setErrorWords(prev => [...prev, word.id]);
      } else {
        setErrorWords(prev => [...prev, word.id]);
        setGameState(prev => {
          const newLives = prev.lives - 1;
          if (newLives <= 0) {
            handleGameOver();
            return { ...prev, lives: 0, time: 0 };
          }
          return { ...prev, lives: newLives, time: Math.max(0, prev.time - 5) };
        });
      }
    }
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const nextProgress = [...konamiProgress, e.key];
      const matchLength = nextProgress.length;
      const expected = KONAMI_CODE.slice(0, matchLength);
      if (JSON.stringify(nextProgress) === JSON.stringify(expected)) {
        if (matchLength === KONAMI_CODE.length) {
          unlockAchievement('hidden_discoverer');
          setShowKonamiEffect(true);
          setView(GameView.EDITOR);
          setKonamiProgress([]);
        } else { setKonamiProgress(nextProgress); }
      } else { setKonamiProgress([]); }
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [konamiProgress]);

  const LevelCard = ({ level }: { level: Level }) => {
    const cats = Array.from(new Set(level.words.map(w => w.category))) as WordClass[];
    return (
      <div className="bg-white rounded-3xl p-6 shadow-xl border-b-4 border-indigo-100 hover:shadow-2xl transition-all">
         <h3 className="text-xl font-black text-indigo-900 mb-2">{level.title}</h3>
         <p className="text-slate-400 text-xs line-clamp-2 mb-4 italic leading-relaxed">"{level.text}"</p>
         <div className="flex flex-wrap gap-2">
            {cats.map(cat => (
              <button 
                key={cat} 
                onClick={() => startGame(level, cat, 'PRACTICE')}
                className="px-3 py-1.5 bg-indigo-50 hover:bg-indigo-600 hover:text-white text-indigo-600 rounded-xl text-[10px] font-black uppercase transition-all shadow-sm"
              >
                {getPluralCategory(cat)}
              </button>
            ))}
         </div>
      </div>
    );
  };

  return (
    <div className={`min-h-screen w-full flex flex-col items-center justify-center p-4 bg-gradient-to-br from-blue-400 via-indigo-400 to-purple-500 overflow-hidden transition-all duration-1000 ${showKonamiEffect ? 'konami-active' : ''}`}>

      {lastUnlocked && (
        <div className="fixed top-8 right-8 z-[100] bg-white p-4 rounded-2xl shadow-2xl border-4 border-yellow-400 animate-in slide-in-from-right duration-500 flex items-center space-x-4">
          <div className="w-12 h-12 bg-yellow-400 rounded-xl flex items-center justify-center text-indigo-900 text-xl"><i className={`fas ${lastUnlocked.icon}`}></i></div>
          <div><span className="block text-[10px] font-black text-yellow-600 uppercase tracking-widest">¡Logro!</span><span className="block text-lg font-black text-indigo-900">{lastUnlocked.title}</span></div>
        </div>
      )}

      {view === GameView.MENU && (
        <div className="flex flex-col items-center animate-in fade-in zoom-in duration-700">
          <h1 className="text-9xl font-black text-white italic drop-shadow-[0_15px_15px_rgba(0,0,0,0.3)] tracking-tighter mb-16 select-none">
            GRAMMA<span className="text-yellow-300">CAT</span>
          </h1>

          <div className="flex flex-col md:flex-row gap-10">
            <button 
              onClick={() => setView(GameView.LEVEL_SELECT)}
              className="group relative w-72 h-72 bg-white rounded-[3rem] shadow-2xl border-b-8 border-indigo-200 hover:scale-105 active:scale-95 transition-all flex flex-col items-center justify-center overflow-hidden"
            >
              <div className="absolute inset-0 bg-indigo-600 opacity-0 group-hover:opacity-10 transition-opacity"></div>
              <i className="fas fa-graduation-cap text-7xl text-indigo-500 mb-4 group-hover:rotate-12 transition-transform"></i>
              <span className="text-3xl font-black text-indigo-900 uppercase italic tracking-tighter">PRÁCTICA</span>
              <p className="text-xs font-bold text-slate-400 mt-2">Explora y elige textos</p>
            </button>

            <button 
              onClick={startRandomChallenge}
              className="group relative w-72 h-72 bg-yellow-400 rounded-[3rem] shadow-2xl border-b-8 border-yellow-600 hover:scale-105 active:scale-95 transition-all flex flex-col items-center justify-center overflow-hidden"
            >
              <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-20 transition-opacity"></div>
              <i className="fas fa-fire text-7xl text-indigo-900 mb-4 group-hover:scale-125 transition-transform animate-pulse"></i>
              <span className="text-3xl font-black text-indigo-900 uppercase italic tracking-tighter">RETO</span>
              <p className="text-xs font-bold text-indigo-800/60 mt-2">¡Partida rápida aleatoria!</p>
            </button>
          </div>

          <div className="mt-16 flex gap-4">
            <button onClick={() => setView(GameView.ACHIEVEMENTS)} className="px-8 py-3 bg-white/20 hover:bg-white/40 text-white rounded-2xl font-black border-2 border-white/30 transition-all flex items-center">
              <i className="fas fa-trophy mr-3"></i> LOGROS
            </button>
          </div>
        </div>
      )}

      {view === GameView.LEVEL_SELECT && (
        <div className="w-full max-w-6xl flex flex-col items-center animate-in slide-in-from-right duration-500 overflow-y-auto max-h-[90vh] custom-scrollbar p-6">
          <div className="w-full flex justify-between items-center mb-10">
            <button onClick={() => setView(GameView.MENU)} className="p-4 bg-white/20 text-white rounded-full hover:bg-white/40 transition-all shadow-lg"><i className="fas fa-arrow-left text-2xl"></i></button>
            <h2 className="text-5xl font-black text-white uppercase italic tracking-tighter drop-shadow-md">MODO PRÁCTICA</h2>
            <div className="w-12"></div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 w-full">
            <div className="space-y-6">
               <h3 className="text-2xl font-black text-yellow-300 uppercase tracking-tighter flex items-center drop-shadow-md">
                 <i className="fas fa-book-open mr-3"></i> Textos Base
               </h3>
               {levels.map(lvl => <LevelCard key={lvl.id} level={lvl} />)}
            </div>
            <div className="space-y-6">
               <h3 className="text-2xl font-black text-cyan-300 uppercase tracking-tighter flex items-center drop-shadow-md">
                 <i className="fas fa-cloud mr-3"></i> Comunidad
               </h3>
               {isLoadingCommunity ? <div className="text-white text-center py-10 animate-pulse"><i className="fas fa-spinner fa-spin text-4xl mb-2 block"></i> Cargando niveles...</div> : (
                 communityLevels.length > 0 ? communityLevels.map(lvl => <LevelCard key={lvl.id} level={lvl} />) : 
                 <p className="text-white/40 italic text-center py-10 bg-black/10 rounded-3xl border-2 border-dashed border-white/10">No hay textos online disponibles aún.</p>
               )}
            </div>
          </div>
        </div>
      )}

      {view === GameView.PLAYING && currentLevel && gameState.targetCategory && (
        <div className="w-full flex flex-col items-center justify-center animate-in zoom-in duration-500">
          <GameHUD state={gameState} target={gameState.targetCategory} />

          <div className="w-full max-w-5xl bg-white rounded-[5rem] p-20 shadow-2xl border-b-8 border-indigo-200 min-h-[450px] flex flex-col justify-center relative">
            <div className="relative z-10 flex flex-wrap justify-center items-center gap-x-6 gap-y-8 text-5xl font-black text-slate-800 leading-normal">
              {currentLevel.words.map((w) => (
                <span 
                  key={w.id} 
                  onClick={() => handleWordClick(w)} 
                  className={`cursor-pointer px-6 py-2 rounded-[2rem] transition-all duration-300 transform select-none
                    ${foundWords.includes(w.id) ? 'bg-green-500 text-white shadow-[0_8px_0_rgb(22,163,74)] -rotate-3 scale-110 pointer-events-none' : ''}
                    ${errorWords.includes(w.id) ? 'bg-rose-500 text-white shadow-lg rotate-3 scale-110 opacity-40 pointer-events-none' : ''}
                    ${cleanedWords.includes(w.id) ? 'opacity-20 grayscale pointer-events-none scale-90' : ''}
                    ${highlightedWords.includes(w.id) && !foundWords.includes(w.id) ? 'ring-8 ring-yellow-400 animate-pulse shadow-yellow-200' : ''}
                    ${!foundWords.includes(w.id) && !errorWords.includes(w.id) && !cleanedWords.includes(w.id) ? 'hover:bg-indigo-50 hover:text-indigo-600' : ''}
                  `}
                >
                  {w.text}
                </span>
              ))}
            </div>

            {!gameState.isPlaying && !gameState.isGameOver && (
              <div className="absolute inset-0 bg-green-500/20 backdrop-blur-sm flex flex-col items-center justify-center z-50 animate-in fade-in duration-300 rounded-[5rem]">
                <div className="bg-white p-12 rounded-[3rem] shadow-2xl border-8 border-green-500 text-center scale-110">
                   <h2 className="text-6xl font-black text-indigo-900 mb-2 italic tracking-tighter">¡TEXTO SUPERADO!</h2>
                   <div className="flex justify-center gap-4 text-3xl mb-4">
                      <i className="fas fa-star text-yellow-400 animate-bounce"></i>
                      <i className="fas fa-star text-yellow-400 animate-bounce [animation-delay:200ms]"></i>
                      <i className="fas fa-star text-yellow-400 animate-bounce [animation-delay:400ms]"></i>
                   </div>
                   <p className="text-xl font-bold text-green-600 uppercase tracking-widest">Recompensa obtenida</p>
                </div>
              </div>
            )}
          </div>

          <div className="mt-12 flex gap-8">
            <button 
              onClick={() => usePowerup('hint')}
              disabled={gameState.powerups.hints <= 0}
              className={`w-32 h-32 flex flex-col items-center justify-center rounded-[2rem] shadow-xl border-b-8 transition-all active:scale-95
                ${gameState.powerups.hints > 0 ? 'bg-cyan-300 border-cyan-500 hover:bg-cyan-200' : 'bg-slate-200 border-slate-300 opacity-50'}
              `}
            >
              <i className="fas fa-lightbulb text-4xl text-cyan-800 mb-1"></i>
              <span className="text-xs font-black text-cyan-900 uppercase">PISTA ({gameState.powerups.hints})</span>
            </button>

            <button 
              onClick={() => usePowerup('clean')}
              disabled={gameState.powerups.cleaners <= 0}
              className={`w-32 h-32 flex flex-col items-center justify-center rounded-[2rem] shadow-xl border-b-8 transition-all active:scale-95
                ${gameState.powerups.cleaners > 0 ? 'bg-rose-300 border-rose-500 hover:bg-rose-200' : 'bg-slate-200 border-slate-300 opacity-50'}
              `}
            >
              <i className="fas fa-broom text-4xl text-rose-800 mb-1"></i>
              <span className="text-xs font-black text-rose-900 uppercase">LIMPIAR ({gameState.powerups.cleaners})</span>
            </button>

            <div className={`w-32 h-32 flex flex-col items-center justify-center rounded-[2rem] shadow-xl border-b-8 transition-all
                ${gameState.powerups.shields > 0 ? 'bg-lime-300 border-lime-500 ring-4 ring-lime-400/50' : 'bg-slate-200 border-slate-300 opacity-50'}
              `}
            >
              <i className="fas fa-shield-alt text-4xl text-lime-800 mb-1"></i>
              <span className="text-xs font-black text-lime-900 uppercase">ESCUDO ({gameState.powerups.shields})</span>
            </div>
          </div>
        </div>
      )}

      {view === GameView.GAME_OVER && (
        <div className="text-center bg-white p-16 rounded-[4rem] shadow-2xl border-x-8 border-b-8 border-rose-500 animate-in zoom-in duration-300">
          <i className="fas fa-skull text-8xl text-rose-500 mb-6 block"></i>
          <h2 className="text-7xl font-black text-slate-900 italic tracking-tighter mb-4">GAME OVER</h2>
          <p className="text-2xl font-bold text-slate-400 mb-10 italic">¡No te rindas, vuelve a intentarlo!</p>
          <button onClick={() => setView(GameView.MENU)} className="w-full py-6 bg-indigo-600 hover:bg-indigo-500 text-white rounded-3xl text-3xl font-black shadow-lg transition-all">MENÚ PRINCIPAL</button>
        </div>
      )}

      {view === GameView.ACHIEVEMENTS && <AchievementsModal achievements={achievements} onClose={() => setView(GameView.MENU)} />}
      {view === GameView.EDITOR && (
        <Editor onClose={() => setView(GameView.MENU)} onSave={(newLevel) => {
          setLevels(prev => [newLevel, ...prev]);
          setView(GameView.MENU);
        }} />
      )}
    </div>
  );
};

export default App;

